2023년 9월26일 로마서 6장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 죄(1,2,6.7.10절), 죽으심(3,4,5,10절), 합하여 세례(3,4절), 연합(5절)
4.주제만들기 : 십자가의 사랑으로 죄에서 벗어날 수 있는 우리
5.하나님 찾기 (관찰)
- 십자가 사랑을 통해 우리가 죄에서 벗어나 의롭게 살 수 있도록 하심
6.인간 찾기 (관찰)
- 예수님과 합하여 세례를 받았으므로 예수님과 연합하게 되었고 죄에 종 노릇하지 않게 됨
- 바울은 예수님과 함께 죽으면 함께 살 것을 믿음으로 강조함
7.하나님 찾기 (해석) 
- 하나님의 사랑은 모두에게 적용된다. 부자이든 가난하든, 지위가 높든 낮든, 다양한 환경, 다양한 상황 등 어떠한 경우에도 적용된다. 그것이 십자가의 사랑이고 죄에서 벗어나 새소망을 가질 수 있는 원동력이다.
8.인간(해석):
- 예수님을 경험했음에도 불구하고 여전히 과거의 삶에 얽매여 있거나, 예수님을 알지 못하는 자들에게 바울은 예수님의 십자가 매달리심과 부활은 우리의 연약한 죄를 덮어주고 죄에서 벗어나 다시 살아갈 소망이 있음을 말한다. 그리고 예수님과 연합된 몸으로 죄에서 벗어나야 함을 강조한다.
9. 적용(나):
- 로마서의 시대와 현재의 시대가 크게 다르지 않다고 생각한다. 죄라는 것을 모르는 세대, 죄가 아니라고 생각하는 세대에 살고 있는 우리가 이상한 사람으로 여겨지고 있는 세대에 살고 있음을 감사한다. 우리가 해야할 것이 참 많다.
- 여전히 죄와 싸우고 있다. 그럼에도 불구하고 소망을 갖는건 나의 죄를 위해 대신 십자가에 매달린 예수님께서 죄에서 벗어나게 해주실 능력이 있다는 것이다. 예수님께 간절히 기도하며 죄에서 벗어나길 소망한다.
- 예수님과 연합해 있다는 것을 잊지 말아야겠다. 늘 예수님과 함께 한다는 사실을 인식하며 살아가는 한 주, 한 달, 한 해, 평생이 되고 싶다.
10. 영적터치(단어/구절) 
만일 우리가 그리스도와 함께 죽었으면 또한 그와 함께 살 줄을 믿노니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-13', '로마서', '6장 11절 ~ 23절', '제목 없음', '(로마서 6장)
11. 이와 같이 너희도 너희 자신을 죄에 대하여는 죽은 자요 그리스도 예수 안에서 하나님께 대하여는 살아 있는 자로 여길지어다
12. 그러므로 너희는 죄가 너희 죽을 몸을 지배하지 못하게 하여 몸의 사욕에 순종하지 말고
13. 또한 너희 지체를 불의의 무기로 죄에게 내주지 말고 오직 너희 자신을 죽은 자 가운데서 다시 살아난 자 같이 하나님께 드리며 너희 지체를 의의 무기로 하나님께 드리라
14. 죄가 너희를 주장하지 못하리니 이는 너희가 법 아래에 있지 아니하고 은혜 아래에 있음이라
15.  그런즉 어찌하리요 우리가 법 아래에 있지 아니하고 은혜 아래에 있으니 죄를 지으리요 그럴 수 없느니라
16. 너희 자신을 종으로 내주어 누구에게 순종하든지 그 순종함을 받는 자의 종이 되는 줄을 너희가 알지 못하느냐 혹은 죄의 종으로 사망에 이르고 혹은 순종의 종으로 의에 이르느니라
17. 하나님께 감사하리로다 너희가 본래 죄의 종이더니 너희에게 전하여 준 바 교훈의 본을 마음으로 순종하여
18. 죄로부터 해방되어 의에게 종이 되었느니라
19. 너희 육신이 연약하므로 내가 사람의 예대로 말하노니 전에 너희가 너희 지체를 부정과 불법에 내주어 불법에 이른 것 같이 이제는 너희 지체를 의에게 종으로 내주어 거룩함에 이르라
20. 너희가 죄의 종이 되었을 때에는 의에 대하여 자유로웠느니라
21. 너희가 그 때에 무슨 열매를 얻었느냐 이제는 너희가 그 일을 부끄러워하나니 이는 그 마지막이 사망임이라
22. 그러나 이제는 너희가 죄로부터 해방되고 하나님께 종이 되어 거룩함에 이르는 열매를 맺었으니 그 마지막은 영생이라
23. 죄의 삯은 사망이요 하나님의 은사는 그리스도 예수 우리 주 안에 있는 영생이니라

