하나님이 이땅에 죄로 포로된 백성들을 구원하시고 죄의 포로된 자녀들에게 자유와 해방을 시키기위하여 독생자예수를 보내셨다. 그 자녀들은 죄와 싸워야 하는데 육신이 연약하여 번번히 싸움에서 질수밖에 없다. 하지만 그 싸움에서 승리하는 방법 즉 죄로부터 자유를 찾는것은 13절에 기록된 말씀처럼 하나님께 드리는 행위를 할때 큰 해방감을 가질수 있다. 죄가 우리를 묶지 못하도록 하나님의 종 된것을 순간순간 선포할때 사탄의 어두움은 도망칠것이다.

