4.주제 만들기: 죄를 깨닫게 하는 율법

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 사람이 살 동안만 주관하는 법
- 남편 있는 여인은 그 남편이 죽으면 그 법에서 자유로움
- 남편 있는 여인은 그 남편 생전에 다른 남자에게 가면 음녀임
- 그 남편이 죽으면 그 법에서 자유롭게 됨
- 그리스도인들은 율법에 대하여 죽었고 율법에서 벗어남
- 그러나 율법으로 인해 우리는 죄를 알게 됨 

7.하나님 찾기 (해석) 

8.인간(해석): 
- 그리스도인들이 율법에 대하여 죽은 것은 우리가 그리스도에게 가서 하나님을 위하여 열매를 맺게 하는 것임.
- 율법에 탐하지 말라고 써있기 때문에 탐심이 죄라는 것을 알게 되었고 내 속에 탐심의 죄가 많다는 것을 깨닫게 됨.
- 율법을 깨닫지 못했을 때는 남의 것을 탐하더라도 그것이 죄인지 몰랐기 때문에 자유로웠으나 율법을 깨닫자 남의 것을 탐하는 것이 죄인 것을 알게 되었음.
- 탐심의 죄를 지을 수밖에 없으니 사망에 이르게 된다. 

9. 적용(나): 
- 십계명을 잘 지키고 있다고 생각하는 사람들이 있다. 부자 청년이 그랬고 오늘날 누군가가 그렇게 이야기하는 것을 들었다.
- 그렇게 말한 부자 청년은 재물과 예수님 중 재물을 택해 사망에 이르렀고 오늘날 누군가는 탐심을 이기지 못하고 마음껏 죄를 짓다가 결국 그 죄가 드러났다.
- 십계명을 잘 지키고 있다고 생각하는 사람들은 율법을 깨닫지 못한 것이다. 잘 지키고 있다고 착각하는 것일 뿐이다. 우리 인간은 십계명을 지킬 능력이 없다. 10개의 율법도 지킬 능력이 없다. 예수님 오시기 전에 율법 준수는 겉으로 드러나는 것을 판단했을 것이다. 겉으로 판단한다 해도 마지막 계명인 탐심을 지킬 능력이 인간에게는 없는 것인데 율법을 깨닫지 못한 자들은 잘 지키고 있다고 말하는 것이다.
- 예수님께서 십계명을 가르치시며 살인과 간음에 대해 말씀하신 것을 기억해야 한다. 그 말씀은 1계명부터 10계명까지 모두 적용되는 가르침일 것이다. 그렇게 적용해 보면 우리는 십계명을 지킬 수 있는 존재가 아니라는 것을 알 수 있다.
- 그러므로 그저 예수님을 바라보아야 한다. 절대 교만해서는 안 된다. 내 의지로 잘하고 있다고 생각하는 것은 사망에 이르는 죄, 곧 교만이다. 그저 예수님을 바라보아야 한다.

