신약에서 최고의 영성가를 뽑으라면 대부분의 학자들은 사도바울 을 선택한다. 그정도로 그의 영적상태가 늘 충만함을 유지하며 살았던 사람이라 의심치않다. 그런데 그런 사도바울 선생조차도 자신의 마음속에 죄의법에서 자유롭지 못함을 알아채고 비통한 고백을 하는것을 볼수있다 24절이하 "오호라 나는 곤고한 사람이로다 이 사망의 몸에서 누가나를 건재내랴"
그러면서 바로25절에 하나님께 감사함을 나타내고 있다. 그가 깨우친것은 모든사람은 죄인 아담의DNA를  가지고 태어나고 이후에 예수를 믿고나면 마음속에 성령하나님이 들어오시고 비로써 하나님의 자녀가 되고 천국시민이 된다. 그럼에도 하나님은 성령하나님과 동시에 육적인 죄성도 믿는 우리 마음에 허락하신다. 그 문제를 두고 괴로워했던 바울은 큰 깨우침을 통하여 큰감사와 더불어 큰 자유함을 얻는다. 즉 우리는 구원은 받았지만 하나님의 절대적인 도움과 은혜가 필요한 존재들이고 뿐만아니라 우리의 육적인 약함을 깨우치고 회개하며 주님께 나아가면 주님은 우리의 허물을 가려주시고 영적으로 성장시켜 주신다.

9. 적용(나)
죄에대하여 늘 심각성을 가지고 조심하고 경계하며 성령하나님을 더욱 의지하며 살아야겠다.

