7.하나님 찾기(해석)

8. 인간 찾기 (해석)
이 세상에는 구약에 하나님의 율법을 온전히 지킬수있는 사람은 한명도없다. 외형적으로 다른사람 에게 존경받을 정도로 윤리 도덕적 으로 품위를 보이더라도 그 속마음까지 과연 온전하게 청결한사람이 있을까를 반문한다면 대답은 '' NO'' 를 쉽게 말할수 있다. 그런데 본문 6절에 보면 "육신의 생각은 사망이요 영의 생각은생명과 평안이니라"
되어있다. 그럼 모든 믿는 사람이라고 하더라도 조그만한 육신의 생각을 갖더라도 사망받는다는 말인가? 대답은
" NO" 이다.  정답은1절에 있다. "그러므로 이제 그리스도 예수안에 있는 자에게는 결코 정죄함이 없나니" 라고 기록되어있다. 여기에 예수님의 본 마음이 내포되었다. 예수님이 이땅에 오신것은 믿는자나 그렇지 않은자들에게 정죄나 심판을 주려는 목적이 아니라 생명과 풍성한 살을 주시려는 목적이 있는것이다. 다만 믿는자들의 연약함도 아시고 대신 죄와 싸워 승리의 기쁨과 경험을 갖기를 원하신다. 그럼에도 믿는 자녀들이라고 하더라도 개인이 죄와 싸워이길수 없음을 깨우치게 하신다. 싸움의 반복되는 실패로 스스로의 연약함을 깨우치고 크신하나님의 존재에대한 인식과 더불어 사랑을 체험케하신다 . 하나님 존재의 소중함과 그분을 절대적으로 의지하는 법을 절망후에 대부분의 자녀들에게 알려주신다. 즉 하나님은 인간 개인의 능력이 아닌 진심으로 주를 믿고 의지하며 싸워 이기기를 원하신다
이것을 통하여 영적으로 장성한 자녀는 6절에 기록된 말씀처럼 "생명과 평안을 갖는자가 되는 것이다

9. 적용(나)
