INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-18', '로마서', '8장 11절 ~ 20절', '하나님의 아들들', '(로마서 8장)
11 예수를 죽은 자 가운데서 살리신 이의 영이 너희 안에 거하시면 그리스도 예수를 죽은 자 가운데서 살리신 이가 너희 안에 거하시는 그의 영으로 말미암아 너희 죽을 몸도 살리시리라
12 그러므로 형제들아 우리가 빚진 자로되 육신에게 져서 육신대로 살 것이 아니니라
13 너희가 육신대로 살면 반드시 죽을 것이로되 영으로써 몸의 행실을 죽이면 살리니
14 무릇 하나님의 영으로 인도함을 받는 사람은 곧 하나님의 아들이라
15 너희는 다시 무서워하는 종의 영을 받지 아니하고 양자의 영을 받았으므로 우리가 아빠 아버지라고 부르짖느니라
16 성령이 친히 우리의 영과 더불어 우리가 하나님의 자녀인 것을 증언하시나니
17 자녀이면 또한 상속자 곧 하나님의 상속자요 그리스도와 함께 한 상속자니 우리가 그와 함께 영광을 받기 위하여 고난도 함께 받아야 할 것이니라
18 생각하건대 현재의 고난은 장차 우리에게 나타날 영광과 비교할 수 없도다
19 피조물이 고대하는 바는 하나님의 아들들이 나타나는 것이니
20 피조물이 허무한 데 굴복하는 것은 자기 뜻이 아니요 오직 굴복하게 하시는 이로 말미암음이라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 10월 2일 로마서 8장 11~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 11(2)
영: 11(2), 13(2), 16 / 15절 종의 영, 양자의 영
육신/몸: 12(2), 13(2)
그리스도: 11, 17
하나님: 14(2), 16, 17, 19
자녀/아들: 14, 16, 17, 19
상속자: 17(3)
영광: 17, 18
고난: 17, 18
피조물: 19, 20
굴복: 20(2) 

4.주제 만들기: 하나님의 아들들

5.하나님 찾기 (관찰)
- 예수님을 살리신 하나님이 그리스도인도 살리실 것임
- 그리스도인이 하나님의 아들이라 증언하시는 성령님. 

6.인간 찾기 (관찰)
- 영으로서 몸의 행실을 죽이면 살게 됨.
- 하나님의 영으로 인도함을 받으면 하나님의 아들임.
- 그리스도인은 예수님처럼 하나님의 상속자다.
- 하나님의 상속자로서 고난도 함께 받아야 함.

7.하나님 찾기 (해석) 
- 성령님이 인간 안에 거하시면 예수님을 살리신 하나님이 그리스도인도 살리실 것임. 부활을 위해서는 반드시 성령님이 인간 안에 거하셔야 함.
- 아빠, 아버지라고 부를 수 있는 마음을 주심. 더불어 부를 수 있음에 감사와 기쁨이 넘치게 하심.
- 하나님은 피조물이 허무한 데 굴복하는 것을 잠시 허락하심.

8.인간(해석): 
- 육신대로 살면 반드시 죽고 성령의 능력으로 몸의 행실을 죽이면 생명을 얻게 됨.
- 하나님의 영으로 인도함을 받는 자, 곧 몸의 행실을 죽이는 자는 하나님의 아들임.
- 우리가 그리스도로 인해 하나님의 영을 받음으로 이제 신분이 하나님의 양자이기 때문에 하나님을 아빠라고, 아버지라고 부를 수 있음.
- 그리스도인은 하나님의 양자로서 예수님과 함께 하나님의 상속자임.
- 하나님의 상속자라는 영광은 그리스도인에게 큰 영광이 될 것이나, 이 영광을 받기 위해서는 예수님의 고난에 동참해야 함. 
- 그리스도인으로 살아간다는 것은 고난이 반드시 함께 한다는 것임. 그리스도인은 고난이 왔을 때 이상히 여길 것이 아니라 당연한 고난이 왔음을 알고 견뎌내고 인내의 결과, 기쁨을 누려야 함.
- 왜냐하면 현재의 고난은 장차 우리에게 나타날 영광과 비교할 수 없기 때문이다. 
- 피조물들도 인간이 하나님의 아들들이 나타날 것을, 세상이 회복될 것을, 피조물들이 회복 되기를 바라고 있음.

9. 적용(나): 
그리스도인으로서 세상을 살아가는 것이 만만치 않다. 특히 하나님의 일을 할 때 그렇다. 몇 가지 고난을 당하면서 깨닫는 것은 하나님의 일을 하며 받는 고난에는 하나님의 도우심이 반드시 함께한다는 것이다. 고난이 왔을 때 비록 힘들고 지치기도 하지만, 하나님의 도우심과 위로하심을 맛보면 그 고난은 아무것도 아닌 것이 됨을 깨닫게 된다.
그렇기에 그리스도인의 삶은 하나님의 영의 인도하심을 받아 몸의 행실을 날마다 죽이며, 하나님의 아들로서 고난에 당당히 맞서는 그런 자가 돼야 한다.
장차 우리에게 나타날 영광은, 하나님과 함께하는 그 기쁨을 누리는 영광은, 이 땅에서 내가 겪는 모든 고난과 비교할 것이 아니다. 이 땅에서의 고난과 위로가 끝이 아니라 부활과 천국이 있다는 것은 우리에게 소망의 기쁨을 준다.

10. 영적터치(단어/구절)  
18 현재의 고난은 장차 우리에게 나타날 영광과 비교할 수 없도다

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-19', '로마서', '8장 21절 ~ 30절', '제목 없음', '[롬8:21-30]
21 그 바라는 것은 피조물도 썩어짐의 종 노릇 한 데서 해방되어 하나님의 자녀들의 영광의 자유에 이르는 것이니라
22 피조물이 다 이제까지 함께 탄식하며 함께 고통을 겪고 있는 것을 우리가 아느니라
23 그뿐 아니라 또한 우리 곧 성령의 처음 익은 열매를 받은 우리까지도 속으로 탄식하여 양자 될 것 곧 우리 몸의 속량을 기다리느니라
24 우리가 소망으로 구원을 얻었으매 보이는 소망이 소망이 아니니 보는 것을 누가 바라리요
25 만일 우리가 보지 못하는 것을 바라면 참음으로 기다릴지니라
26 이와 같이 성령도 우리의 연약함을 도우시나니 우리는 마땅히 기도할 바를 알지 못하나 오직 성령이 말할 수 없는 탄식으로 우리를 위하여 친히 간구하시느니라
27 마음을 살피시는 이가 성령의 생각을 아시나니 이는 성령이 하나님의 뜻대로 성도를 위하여 간구하심이니라
28 우리가 알거니와 하나님을 사랑하는 자 곧 그의 뜻대로 부르심을 입은 자들에게는 모든 것이 합력하여 선을 이루느니라
29 하나님이 미리 아신 자들을 또한 그 아들의 형상을 본받게 하기 위하여 미리 정하셨으니 이는 그로 많은 형제 중에서 맏아들이 되게 하려 하심이니라
30 또 미리 정하신 그들을 또한 부르시고 부르신 그들을 또한 의롭다 하시고 의롭다 하신 그들을 또한 영화롭게 하셨느니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 10월3일 로마서 8장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천) 
- 피조물(21,22절), 성령(23,26,27절), 간구(26,27절)
4.주제만들기
5.하나님 찾기 (관찰)
- 성령께서 친히 우리의 연약함을 도와주심
- 성령은 친히 말할 수 없는 탄식으로 우리를 위해 간구하심
- 마음을 살피시는 분이 성령의 생각이 무엇인지 알고 계심
- 성령은 하나님의 뜻대로 성도를 위하여 간구하심
- 미리아신 사람들을 자기 아들의 형상을 닮게 하시려고 미리 정하심
- 하나님께서 미리 정하신 그들을 부르시고 부르신 그들을 의롭다 하시고의롭다 하신 그들을 영화롭게 하심
6.인간 찾기 (관찰)
- 바울은 피조물인 우리가 썩어짐의 종 노릇하는데서 벗어나 하나님의 자녀가 누릴 영광의 자유에 이를 것이라고 말함.
7.하나님 찾기 (해석) 
- 하나님은 우리의 연약함을 알고 계시지만 직접 개입할 수 있음에도 우리를 위해 말할 수 없는 탄식으로 기도하며 간구하신다. 우리에게 주어진 자유의지가 있음에도 성령님께서 우리를 위해 간구하신다는 사실은 놀랍다. 성령님의 간구로 소망 없는 피조물이 소망을 볼 수 있다는 것이 얼마나 감사한지 깨닫는다.
8.인간(해석)
- 예수님과 같은 삶을 살아야하는 우리에게 예수님과 같이라는 것은 연약한 육체로는 불가능한 일이다. 그렇기 때문에 당시 예수님을 믿는 사람들이 유대인의 핍박에도 힘들지만 자기 자신의 연약함으로 인해 넘어질 일이 참 많았을 것 같다.
- 하나님께서 어떤 존재이고, 우리는 왜 존재하며, 세상에서 어떤 일들을 감당해야하는지 깨닫느다면 하나님께서 우리에게 맡겨주신 사명이 얼마나 힘든 일인지 알 것이다. 힘든 일로 인해 실족할 수 있지만 감사한 것은 나를 위해 힘쓰시는 성령님으로 인해 다시 일어나 도전할 용기가 생긴다는 것이다.
9. 적용(나): 
- 나를 위해 간구하시는 성령님께 감사하다. 내가 이겨내야할 죄성과 주님의 소명을 잘 감당하도록 힘써 기도해야겠다. 
10. 영적터치(단어/구절)
-만일 우리가 보지 못하는 것을 바라면 참음으로 기다릴지니라
-이와 같이 성령도 우리의 연약함을 도우시나니 우리는 마땅히 기도할 바를 알지 못하나 오직 성령이 말할 수 없는 탄식으로 우리를 위하여 친히 간구하시느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-20', '로마서', '8장 31절 ~ 39절', '제목 없음', '(로마서 8장)
31.  그런즉 이 일에 대하여 우리가 무슨 말 하리요 만일 하나님이 우리를 위하시면 누가 우리를 대적하리요
32. 자기 아들을 아끼지 아니하시고 우리 모든 사람을 위하여 내주신 이가 어찌 그 아들과 함께 모든 것을 우리에게 주시지 아니하겠느냐
33. 누가 능히 하나님께서 택하신 자들을 고발하리요 의롭다 하신 이는 하나님이시니
34. 누가 정죄하리요 죽으실 뿐 아니라 다시 살아나신 이는 그리스도 예수시니 그는 하나님 우편에 계신 자요 우리를 위하여 간구하시는 자시니라
35. 누가 우리를 그리스도의 사랑에서 끊으리요 환난이나 곤고나 박해나 기근이나 적신이나 위험이나 칼이랴
36. 기록된 바 우리가 종일 주를 위하여 죽임을 당하게 되며 도살 당할 양 같이 여김을 받았나이다 함과 같으니라
37. 그러나 이 모든 일에 우리를 사랑하시는 이로 말미암아 우리가 넉넉히 이기느니라
38. 내가 확신하노니 사망이나 생명이나 천사들이나 권세자들이나 현재 일이나 장래 일이나 능력이나
39. 높음이나 깊음이나 다른 어떤 피조물이라도 우리를 우리 주 그리스도 예수 안에 있는 하나님의 사랑에서 끊을 수 없으리라

