6.인간 찾기(관찰)

7.하나님 찾기(해석)
가장 거룩하시고 전능하신 하나님 께서 피조물인 인간을 위하여 자신의  독생자 예수를 아끼지 않으시고 내주셨다. 그러한 하나님의 크신사랑에 대항하여 믿음의 자녀들을 해칠 세력이 있을수 없다. 뿐만아니라 십자가에서 죽으시고 부활하신 예수께서 연약한 우리를 위하여 간구까지 하시고 계시니 얼마나 감사가되며 큰위로가 되지않을수 있을까? 하나님의 사랑은 너무 위대하셔서 사망의 권세 조차도 하나님과 믿는사람들의 관계를 끊을수 없다. 
