2023년 10월 5일 로마서 9장 1~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제 만들기: 민족을 향한 바울의 사랑
5.하나님 찾기 (관찰)
- 아브라함의 씨가 다 그의 자녀가 아니라 오직 이삭으로부터 난 자라야 네 씨라 불리리라 하심
- 명년 이 때에 내가 이르리니 사라에게 아들이 있으리라 하심
6.인간 찾기 (관찰)
- 바울에게 큰 근심과 마음에 고통이 있음
- 자신이 그리스도에게서 끊어지더라도 이스라엘의 구원을 바라는 바울
7.하나님 찾기 (해석) 
8.인간(해석):
- 이스라엘 백성들이 예수님을 믿지 않을 뿐 아니라 예수님 믿는 자들을 박해하는 것이 바울에게는 큰 괴로움이었음.
- 이런 이스라엘 백성들이 구원받기를 원하는 정도가 얼마나 컸으면 바울은 자신이 구원받지 못할지라도 이스라엘이 구원받기를 바람.
- 하나님의 약속은 이스마엘이 아니라 이삭의 계보에서 성취된다. 이스마엘은 인간의 방법으로 태어났고, 이삭은 하나님의 말씀대로, 하나님이 하신 약속대로 태어났다.
- 아브라함과 사라의 방법이 아니라 아브라함과 사라가 하나님을 믿는 믿음으로 낳은 이삭의 계보가 약속의 계보이다.
9. 적용(나): 
- 모세가 하나님의 부르심을 받아 시내산에서 십계명을 받고 내려올 때에 아론과 백성들이 금송아지를 만들어 제사하며 즐거워하고 있었다. 그 모습을 가장 싫어하시는 하나님께서 백성들을 멸하려 하셨고 모세가 백성들 대신 자기를 죽이시고 저들을 살려달라고 하나님께 간절히 기도한다. 
- 유대인을 향한 바울의 마음이 모세와 같았다. 나는 우리 민족을 이렇게 사랑할 수 있는가? 나와 관계된 사람을 위해서는 어쩌면 할 것 같다. 내 아내, 아들, 누나 그러나 믿지 않는 민족을 위해 내가 그럴 수 있는가? 하아... 정말 어렵다. 
- 그런데 놀랍게도 나도 과거에 기도하던 중 이들을 흉내 내며 “제 이름을 생명책에서 지워주시고 우리 민족을, 믿지 않는 이들을 구원해 주세요.” 라고 기도했던 때가 있었다. 
내가 대체 왜 그랬을까..? 나는 그런 사랑도 없고 용기도 낼 수 없는 존재인데.
그 기도는 나의 기도가 아니라 예수님의 기도였던 것 같다.
- 하나님의 영에 강하게 붙잡힌 이들은 모세와 바울처럼 위대한 기도와 간구를 할 수 있다. 그러나 어쩌면 그것은 인간의 마음이 아닐 것이다. 
모세와 바울은 아니더라도 나의 경험을 비춰봤을 때 그렇다는 것이다. 
- 우리는 계속해서 하나님께 붙들린 삶을 살아야 한다. 하늘 문이 열린 삶을 살 때 내가 원치 않는 것, 내가 바라지 않는 것까지 원하고 바랄 수 있게 된다. 
- 그것은 바로 예수님의 소원이다.
10. 영적터치(단어/구절) 
1 내 양심이 성령 안에서 나와 더불어 증언하노니
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

