8.인간(해석):


	하나님의 뜻을 헤아리기에 어려울 때 하나님에 대한 의문을 품을 수 있다고 말한다. 우리는 하나님의 뜻을 온전히 이해할 수 없는 제한적인 존재이기에 하나님의 뜻에 의심을 품거나 반문하는 것은 적절하지 않다고 말한다.


9. 적용(나): 


	나에게 왜 이런 상황을 만드셨냐고 반문할 수 있지만, 사실은 그 상황은 내가 만든 상황이다. 그런데 하나님의 뜻을 모르겠다. 하나님의 훈련이다. 내 멋대로 해석하는 경우가 있다. 하나님이 정확히 말씀하지도 않으셨고 하나님의 뜻을 구하려하지도 않았다. 나의 잘못된 생각을 회개한다.
	하나님의 뜻일 수도 있음을 인정한다. 하나님의 뜻임을 알 수 있도록 기도해야겠다.


