2023년 10월 9일 10장 11~21절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
주: 12(2), 13
전파: 14, 15
들음: 17(2)
말씀: 17, 18
이스라엘: 19, 21
백성: 19(2), 21

4.주제 만들기: 듣지 않으면 알 수 없는 복음

5.하나님 찾기 (관찰)
- 한 분이신 주께서 모든 사람의 주가 되시고, 그를 부르는 모든 사람에게 부요하심
- 이스라엘에게 종일 내 손을 벌렸노라

6.인간 찾기 (관찰)
- 이스라엘이 복음에 순종하지 않음

7.하나님 찾기 (해석) 
- 이스라엘에게 계속해서 복음을 전하셨지만, 이스라엘은 듣지 않고 있음.

8.인간(해석): 
- 누구든지 주의 이름을 부르는 자는 구원을 받지만, 복음이 무엇인지 듣지 못하면 주의 이름을 부를 수가 없음.
- 믿음은 들음에서 나기 때문에 듣지 못하면 알수도 믿을 수도 없음.
- 듣지 못한 이에게 복음을 전할 사람이 반드시 필요함.
- 이스라엘이 듣지 않고 완고할 때 복음은 이스라엘이 백성이 아니라고 생각하는 자와 미련한 자들에게 전파가 될 것이라고 예언되어 있음.
- 하나님은 선지자들과 복음 전도자를 통해 이스라엘에게 계속 복음을 전하셨으나 이스라엘은 순종하지 않고 거슬러 말함.
- 이런 이스라엘에게 하나님은 계속해서 손을 벌리심.

9. 적용(나): 
- 복음을 듣지 못한 사람들이 아직도 많다. 땅, 하늘, 바다, 그리고 그 안에 있는 모든 것을 보면 하나님의 흔적이 가득하다. 그것들을 보고 하나님을 느낄 수 있도록 하나님이 세상과 인간을 창조하셨다. 그러나 복음은 반드시 사람을 통해 사람이 들어야 한다.
- 복음을 한 번도 듣지 못한 장조모님 임종 때 가까운 친척들이 마지막 인사를 하고 있었다. 나는 그들보다 관계가 가깝지 않기 때문에 복음을 전하겠다고 시간을 달라고 말하기가 어려웠다. 친척들이 많았기 때문에 오늘 복음을 못 전하게 될 수 있겠다 생각하고 있을 때 ‘믿음은 들음에서 나며 들음은 그리스도의 말씀으로 말미암느니라’ 는 구절이 떠올랐다. 결국 복음을 전했고 의식이 없던 장조모님은 내 손을 꼭 잡으며 눈물을 흘리셨다.
- 복음을 전하는데 머뭇거릴 이유가 없다. 기회가 왔을 때 반드시 전해야 한다. 우리 생각보다 복음을 듣지 못한 이들이 많다.
- 직장, 지역사회(동네, 동호회 등)에서 그리스도의 편지로서의 삶을 살면, 반드시 주변 사람들이 도전받게 되어 있다. 그리고 복음을 전할 기회가 반드시 온다. 그때 복음을 자연스레 전해야 한다. 의외로 복음을 듣기를 기다리는 사람들이 많다.
- 시간이 주어지면 노방전도를 가야 한다. 조퇴해서라도 초중고등학교 하교 시간에 사탕 초콜릿 들고 복음을 전해야 한다. 시간이 많지 않다. 내가 언제, 동네 사람들이 언제 생명을 다할지 모르는데 이대로 있을 순 없다.


10. 영적터치(단어/구절)  
14 듣지도 못한 이를 어찌 믿으리요 전파하는 자가 없이 어찌 들으리요

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-26', '로마서', '11장 1절 ~ 10절', '제목 없음', '[롬11:1-10]

1 그러므로 내가 말하노니 하나님이 자기 백성을 버리셨느냐 그럴 수 없느니라 나도 이스라엘인이요 아브라함의 씨에서 난 자요 베냐민 지파라

2 하나님이 그 미리 아신 자기 백성을 버리지 아니하셨나니 너희가 성경이 엘리야를 가리켜 말한 것을 알지 못하느냐 그가 이스라엘을 하나님께 고발하되

3 주여 그들이 주의 선지자들을 죽였으며 주의 제단들을 헐어 버렸고 나만 남았는데 내 목숨도 찾나이다 하니

4 그에게 하신 대답이 무엇이냐 내가 나를 위하여 바알에게 무릎을 꿇지 아니한 사람 칠천 명을 남겨 두었다 하셨으니

5 그런즉 이와 같이 지금도 은혜로 택하심을 따라 남은 자가 있느니라

6 만일 은혜로 된 것이면 행위로 말미암지 않음이니 그렇지 않으면 은혜가 은혜 되지 못하느니라

7 그런즉 어떠하냐 이스라엘이 구하는 그것을 얻지 못하고 오직 택하심을 입은 자가 얻었고 그 남은 자들은 우둔하여졌느니라

8 기록된 바 하나님이 오늘까지 그들에게 혼미한 심령과 보지 못할 눈과 듣지 못할 귀를 주셨다 함과 같으니라

9 또 다윗이 이르되 그들의 밥상이 올무와 덫과 거치는 것과 보응이 되게 하시옵고

10 그들의 눈은 흐려 보지 못하고 그들의 등은 항상 굽게 하옵소서 하였느니라

 

