2023년 10월10일 로마서 11장 1절~10절

1.1분기도

2.본문성경 읽기(3번)

3.반복단어 찾기(형광펜 추천)


	(1,2절), 이스라엘(1,2,7절), 은혜(5,6절), 보지 못하다(8,10절)


4.주제만들기

5.하나님 찾기 (관찰)


	백성을 버리지 않으시는 분, 지킬자를 예비하시는 하나님
	심령과 보지 못하는 눈과 듣지 못하는 귀를 주심


6.인간 찾기 (관찰)


	선택받은 자들
	구하는 것을 얻지 못하고 택하심을 입은 자가 얻음


7.하나님 찾기 (해석) 


	우리를 버리지 않으시고 지킬 자를 예비하시는 분이시다. 
	혼미한 심령과 보지 못하는 눈과, 듣지 못하는 귀를 두심은 하나님을 더 의지하고 구별되게 하려는 하나님의 뜻임을 신뢰한다.


8.인간(해석):


	백성은 택하심을 받아 은혜로 메시아를 볼 수 있었지만 그들의 심령이 혼미케 되어 가려진 눈과 막힌 귀로 메시아를 볼 수 없었다. 은혜를 교만의 도구로 전락시켰다.


9. 적용(나): 


	끊임없이 우리를 붙잡아 주시는 분이다. 그리고 우리를 지키시는 분이다.  우리가 하나님을 의지하고 하나님을 따르길 원하신다. 단지 하나님 자신을 의지하길 원하는 간절한 마음으로 아무 존재도 아닌 우리를 보호해주신다. 하나님의 깊은 사랑에 감사한다. 



	백성은 하나님께 택하심을 받은 족속이다. 그런데 택하심을 받았다는 그 은혜가 교만이 되어 백성의 심령을 혼미케 했고, 눈을 가렸으며, 귀는 닫게 만들었다. 그로 인해 우리에게 복음이 전달되었다. 우리도 마찬가지이다. 복음을 알지 못하는 자들에 비해 빨리 복음을 알게 되었고 그로 인한 축복을 누리고 있다. 그런데 이런 은혜와 축복이 내 심령을 혼미케 하여 교만하게 하고, 악을 생각하고 계획하고 실행하게 한다. 내게 주어진 은혜가 나를 성장케 하는 것이 아니라 나를 더 교만케 했다. 하나님의 뜻이 아니다. 회개하고 돌이켜 하나님을 전적으로 의지하고 주님이 주신 소명을 쫓아가는 삶을 살아야 한다. 
	먼저 받은 자로서,  올바르게 해석하는 지혜가 있길 소망한다. 올바른 세상 사람들에게 전할 수 있도록 노력해야겠다. 


10. 영적터치(단어/구절) : 

이스라엘이 구하는 그것을 얻지 못하고 오직 택하심을 입은 자가 얻었고 그 남은 자들은 우둔하여졌느니라

11. 믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-27', '로마서', '11장 11절 ~ 20절', '제목 없음', '(로마서 11장)
11. 그러므로 내가 말하노니 그들이 넘어지기까지 실족하였느냐 그럴 수 없느니라 그들이 넘어짐으로 구원이 이방인에게 이르러 이스라엘로 시기나게 함이니라
12. 그들의 넘어짐이 세상의 풍성함이 되며 그들의 실패가 이방인의 풍성함이 되거든 하물며 그들의 충만함이리요
13.  내가 이방인인 너희에게 말하노라 내가 이방인의 사도인 만큼 내 직분을 영광스럽게 여기노니
14. 이는 혹 내 골육을 아무쪼록 시기하게 하여 그들 중에서 얼마를 구원하려 함이라
15. 그들을 버리는 것이 세상의 화목이 되거든 그 받아들이는 것이 죽은 자 가운데서 살아나는 것이 아니면 무엇이리요
16. 제사하는 처음 익은 곡식 가루가 거룩한즉 떡덩이도 그러하고 뿌리가 거룩한즉 가지도 그러하니라
17. 또한 가지 얼마가 꺾이었는데 돌감람나무인 네가 그들 중에 접붙임이 되어 참감람나무 뿌리의 진액을 함께 받는 자가 되었은즉
18. 그 가지들을 향하여 자랑하지 말라 자랑할지라도 네가 뿌리를 보전하는 것이 아니요 뿌리가 너를 보전하는 것이니라
19. 그러면 네 말이 가지들이 꺾인 것은 나로 접붙임을 받게 하려 함이라 하리니
20. 옳도다 그들은 믿지 아니하므로 꺾이고 너는 믿으므로 섰느니라 높은 마음을 품지 말고 도리어 두려워하라

