4.주제 만들기: 하나님의 인자하심에 머무르라

5.하나님 찾기 (관찰)
- 하나님의 인자하심과 준엄하심
- 이방인의 충만한 수가 들어올 때까지 이스라엘 백성을 우둔하게 하심
- 하나님의 은사와 부르심에는 후회하심이 없음

6.인간 찾기 (관찰)
- 하나님의 인자하심과 준엄하심을 말하는 바울
- 접붙임 받은 백성도 하나님의 인자하심에 머무르지 않으면 찍히게 됨
- 이스라엘 백성도 하나님의 인자, 즉 믿음 안에 거하면 다시 접붙임을 받게 됨
- 이방인의 충만한 수가 들어오기까지 이스라엘 백성들은 우둔하게 됨
- 이스라엘 백성들은 조상들로 말미암아 사랑을 입은 자들임
- 이방인들은 이스라엘의 불순종으로 하나님의 긍휼하심을 입게 됨

7.하나님 찾기 (해석) 
- 이방인을 향한 하나님의 사랑과 긍휼하심
- 이스라엘을 향한 하나님의 사랑과 긍휼하심
- 모든 인간을 향한 하나님의 사랑과 긍휼하심, 하나님은 이스라엘과 이방인 모두의 구원을 바라신다.

8.인간(해석): 
- 하나님의 인자하심에 머무르지 않으면, 믿음 안에 거하지 않으면 찍힘을 받는다. 찍힘을 받는 다는 것은 예수님으로부터 분리, 즉 사망을 말한다.
- 불순종하여 찍힘 받은 이스라엘 백성도 하나님의 인자하심에 머무른다면, 즉 믿음 안에 거하면 다시 접붙임 받게 된다. 다시 접붙임 받는다는 것은 예수님과의 연합, 즉 생명을 말한다.

9. 적용(나): 
- 구원받은 백성이라는 기쁨을 누리되, 나의 비참한 본성을 기억하고 겸손하게 주 앞에 엎드려 예수님께 감사드리는 삶을 살아야 한다. 
- 그리고 그리스도인들이 교만함에 빠지지 않도록 말씀을 바르게 전하고 그들에게 본을 보이는 삶을 살아야 한다.
- 주의할 것은 이런 삶을 살아냈다는 교만에 빠지지 않도록 늘 주의하며, 성령의 능력을 의지하여 그런 삶을 살아야 한다.


10. 영적터치(단어/구절)  
  22 너희가 만일 하나님의 인자하심에 머물러 있으면 그 인자가 너희에게 있으리라 그렇지 않으면 너도 찍히는 바 되리라

