4.주제 만들기: 사랑은 율법의 완성이다.

5.하나님 찾기 (관찰)
- 모든 권세는 하나님이 정하신 바라

6.인간 찾기 (관찰)
- 권세를 거스르는 자는 하나님의 명을 거스름이다.
- 선을 행하면 다스리는 자에게 칭찬을 받지만, 악을 행하면 벌을 받는다.
- 사랑의 빚 외에는 아무런 빚도 지지 말라.

7.하나님 찾기 (해석) 

8.인간(해석): 
- 제도와 권력은 하나님이 세상의 질서를 위해 일반은총으로 세우시고 허락하신 것임. 세상의 질서를 위해 권세들에게 복종하는 것이 좋다.
- 악한 일을 하면 다스리는 자에게 벌을 받게 된다. 우리는 악한 일이 아니라 선한 일을 하여 칭찬을 받아야 한다.
- 사랑의 빚 외에는 아무에게든지 아무 빚도 지지 말아야 한다. 사랑하는 자는 율법을 다 이루었다. 이웃을 사랑하는데 이웃에게 범죄(때리고, 훔치고, 속여 빼앗고, 간음하고, 탐하는 등)할 수 없다. 
- 이웃에게 악을 범하면 그것은 악의 빚을 진 것이다. 우리는 사랑을 주고 받아야지 악을 주고 받아서는 안 된다.
- 율법을 지키는 힘은 오직 사랑이다. 율법을 지키는 힘이 사랑에서 나오기 때문에 율법의 완성이 곧 사랑이다.

9. 적용(나): 
- 직장, 지역사회, 나라에서 권세들에게 복종해야 한다. 그러나 도덕과 법을 벗어나거나 성경적이지 못한 권세들이 있다면 양심에 따라 선한 말을 할 수 있어야 한다.
- 그러나 모든 죽어가는 것들을 사랑하는 마음을 갖고, 나한테 주어진 길어 묵묵히 걸어가야 한다.
- 하나님의 사랑을 깨닫는 자가 이웃을 사랑할 수 있다. 하나님의 사랑을 기억하는 자가 이웃을 사랑할 수 있다. 하나님의 사랑을 기억하는 것은 성령의 능력이다. 성령님의 능력으로 하나님의 사랑을 기억하기 위해서는 날마다 경건 시간을 가져야 한다. 이것이 없으면 사랑도 없다.
- 그렇기 때문에 나는 오늘도 내일도 말씀을 읽고 기도를 해야만 한다.

10. 영적터치(단어/구절)  
- 10 사랑은 율법의 완성이니라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

