4.주제만들기 : 인내와 위로는 소망을 가져온다.

5.하나님 찾기 (관찰)


	자신을 기쁘게 하지 않으심
	본 받아 서로 뜻이 같게 하여 주심



	하나님의 진실하심을 위해 우리를 섬기로 오심


6.인간 찾기 (관찰)


	연약한 자의 약점을 담당하고 자신을 기쁘게 하면 안됨



	기쁘게 하되 선을 이루고 덕을 세워야 함
	인내와 위로의 교훈은 소망을 이루게 함


7.하나님 찾기 (해석) 


	통해 예수님과 같이 살아갈 수 있는 소망을 나타내심


8.인간(해석):


	안에서 믿음이 강한 형제가 연약한 형제를 섬길 때, 자신의 기쁨을 위해서가 아닌 하나님의 선을 이루고 덕을 세우는 목적이어야 함.



	과정이 힘들지만 성경을 통해 인내와 위로의 교훈을 얻어 소망이 있다는 확신을 가지고 섬겨야 함. 
	과정을 통해 하나님의 때에 공동체가 한마음 한뜻으로 하나님께 영광 드리게 됨


9. 적용(나):

- 로마서를 읽으며 나에게 있어야 하는 것은 사랑이다. 사랑 없이 섬김을 할 때 내 생각, 내 뜻대로 판단하고 정죄하여 스스로 상처를 입게 만드는 행동을 할 수 있다. 그리고 내 상처가 다른 사람으로 인해 생긴 상처라고 오해하며 살아갈 수 있다. 나 스스로가 만든 상처를 오해하며 살아가는 어리석은 삶을 살게 된다. 섬김에는 반드시 사랑이 동반되어야 한다.

- 누군가를 섬기는 일은 참으로 어렵다. 나의 계획대로 되는 것이 하나도 없기 때문이다. 그럴 때 성경이 주는 교훈은 나에게 위로가 되고 인내하게 하며 하나님이 주시는 비전으로 소망을 보게 한다. 결국 하나님과 동행하며 하나님께 붙어있는 삶을 살면 하나님께서 강한 힘과 능력을 부어주시는 것이다. 


	대해 점검해보는 시간을 가져야겠다. 더 겸손히, 큰 사랑이 내 안에 가득하길 소망한다.


