5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
-바울은 형제, 자매들에게 서로 문안하도록 권면한다.
-형제, 자매들에게 배운 교훈을 거슬러 분쟁을 일으키는 자들을 떠나라고 권면한다.
-선한데 지혜롭고, 악한데 미련하기를 권면한다.
7.하나님 찾기 (해석) 
8.인간(해석):
-바울은 형제, 자매들이 서로 문안하며 위로하고 격려하는 시간을 갖도록 권했다. 이는 많은 어려움에 있음에도 믿음이 흔들리지 않고 사역에 정진하는 서로를 바라보며 힘을 얻고자 함이었을 것 같다. 
-바울은 배운 교훈을 벗어나 분쟁을 일으키는 자들에게서 떠나라고 말하며 선한 데에는 지혜롭고 악한 데는 미련하기를 원한다고 했다. 내가 생각하기엔 선한 데에 순진한 마음, 깨끗한 마음으로 해야 하고, 악한데 지혜로워야 하는데 나의 생각과 반대로 말을 했다. 이것은 선한 일에 지혜가 많이 필요함을 뜻한다. 나는 선한 의도이지만 누군가에게 시험이 들거나 정죄가 되거나 상처가 될 수 있다. 또한 악한 것에는 순진함이 필요한데, 지혜로 악함을 물리치기엔 악이 너무 우리의 연약함을 잘 알고 있어 나의 지혜로 쉽게 이기지 못한다. 악한 것에 발을 대지 않는 순진함이 있어야 악을 이겨낼 수 있다. 즉, 악에는 미련해야 사탄이 유혹조차 할 수 없게 되는 것이다.
9. 적용(나): 
-나의 연약함으로 사탄이 만들어낼 수 있는 유혹거리가 너무 많다. 앞으로의 삶에선 선한 데 지혜롭고, 악한 데 미련한 삶을 살 수 있도록 간절히 기도해야겠다.
10. 영적터치(단어/구절) : 너희가 선한 데 지혜롭고 악한 데 미련하기를 원하노라
