4.주제 만들기: 그리스도의 마음

5.하나님 찾기 (관찰)
- 하나님의 일은 하나님의 영만 알 수 있다.
- 하나님은 그리스도를 믿는 자들에게 하나님의 영을 보내 주셨다.

6.인간 찾기 (관찰)
- 우리가 하나님으로부터 온 영을 받았는데, 이것은 우리로 하여금 하나님께서 우리에게 은혜로 주신 것들을 알게 하려 하심이다.
- 육에 속한 사람은 하나님의 성령의 일들을 받지 않는다. 왜냐하면 그것이 어리석게 보이기 때문이다.
- 신령한 사람은 모든 것을 판단하고 다른 사람에게는 판단 받지 않는다.

7.하나님 찾기 (해석) 
- 하나님의 영을 믿는 자들에게 보내주셨기 때문에 믿는 자들은 하나님의 일을 알 수 있다.
- 하나님의 영을 믿는 자들에게 보내주셨기 때문에 믿는 자들은 하나님이 은혜로 주신 것들을 
알 수 있다.

8.인간(해석): 
- 하나님께서 은혜로 주신 것은 성령님의 가르침을 통해서만 깨달을 수 있다. 
- 육에 속한 사람들은 성령에 속한 일이 어리석게 보이는데, 그것은 자기의 유익을 구하지 않고 오히려 자기를 부인하는 모습이기 때문이다. 내가 잘 살기 위해 남을 누르고 올라가야 하는 구조를 역행하는 모습이 미련해 보이기 때문이다. 
- 신령한 사람들은 하나님의 생각을 아시는 성령님의 가르침을 받기 때문에 다른 사람을 영적으로 판단 할 수 있다. 그러나 믿지 않는 사람은 신령한 사람을 세상적으로 평가할 수 있을 뿐, 영적으로 판단할 수 없다. 

9. 적용(나): 
- 성령님께 꽉 붙들린 삶을 살아야 한다. 인생에 가장 기쁜 일에 집중해야 한다. 보내 주신 곳에서 일을 열심히 하되 늘 주님 말씀을 읇조리고 기도하며, 그렇게 날마다 주님과 함께 걷고, 함께 대화하며 살아가야 한다.
- 세상에서는 자기를 부인하고 자기 십자가를 지고 살아가려고 발버둥 치는 나의 모습 미련해 보일 것이다. 
- 그러나 누군가에게는 그리스도의 편지로 읽힐 것이다. 그리고 그 누군가는 반드시 주님께 돌아올 것이다. 나는 불신자들에게 성경으로 읽혀야 한다.

