5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 시기와 다툼이 있고 악한 사람의 본성을 따라 행하는 것을 말하며 아직도 육에 속해 있는 것에 대해 책망한다. 
- 또한 아볼로파와 바울파와 같이 사역자들을 쫓아 분열되는 것에 대해 책망하고 있다.
- 바울과 아볼로는 심는 자와 물 주는 자로 동역자이고 사역자임을 강조한다. 
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 성도들이 집중해야 할 본질에서 벗어나 육에 속한 사람처럼 행동하는 것을 책망한다. 이것은 인간의 악한 본성에 따르는 것인데 육에 속한 사람처럼 행동하지 말고 믿음의 동역자로서 시기와 다툼 없이 온전히 하나님만 바라보는 믿음을 갖길 소망했기 때문이다.
9. 적용(나): 
- 바울은 신령한 자들을 대하듯이 말하지 않고 어린아이를 대하듯이 말하였다. 젖 먹이는 마음으로 고린도 성도들에게 말하였는데 바울이 한 영혼 한 영혼을 얼마나 소중히 여겼는지 깨달을 수 있다. 예수님을 사랑했던 바울은 예수님처럼 다른 영혼을 사랑했다. 나에게도 같은 마음이 생기기 원한다.
- 우리는 가끔 본질적인 부분에서 벗어나 서로 분열되는 어리석음을 보일 때가 있다. 교회의 교파가 나누어지고 다른 교리로 충돌하며 창조론과 관련된 수많은 이야기로 서로 대립하여 중요한 본질에서 벗어나게 한다. 우리가 알 수 없는 일에 힘을 빼게 하고 서로 다투고 상처 주는 행위는 사탄이 우리를 분열시키고자 하는 계획임을 알아야 한다. 사탄의 계략에 넘어가지 않으려면 지혜롭게 대처할 수 있는 능력이 필요하다. 그러기 위해 노력해야 할 것들에 대해 생각하고 행동해야겠다. 
10. 영적터치(단어/구절)
내게 주신 하나님의 은혜를 따라 내가 지혜로운 건축자와 같이 터를 닦아 두매 다른 이가 그 위에 세우나 그러나 각각 어떻게 그 위에 세울까를 조심할지니라
