세상에서 아무리 존경 받고 인기 있는 삶을 살았다고 하더라도 각자의 마지막 때 평가는 다를 수 있다. 예수님 터 위에 각자 행하였던 것 모든 것을 100% 공적을  통하여 나타나게 된다. 숨기고 싶었던 모든 죄악들 부끄러웠던 모습 등이 다 들어나는 순간이 오는 것이다. 주님을 제대로 믿고 살았던 자녀라면 불을 통한 공적이 그대로 있어 생명의 빛으로 나타나게 될 것임을 바울은 말하고 있다.

