4.주제 만들기: 받은 은혜를 기억하고 교만하지 말라

5.하나님 찾기 (관찰)
- 어둠에 감추인 것들을 드러내고 마음의 뜻을 나타내실 것임

6.인간 찾기 (관찰)
- 그리스도의 일꾼
- 자책할 것이 없으나 이것으로 의롭다 함을 얻지는 못함
- 바울과 아볼로와의 일로 본을 보임

7.하나님 찾기 (해석) 
- 사람들이 누군가를 또는 서로를 칭찬하거나 정죄하지만 모든 것은 주님 앞에 섰을 때 드러나고 충성된 자들은 주님께 칭찬을 받을 것임

8.인간(해석): 
- 일을 맡은 자들에게 구할 것은 충성이다. 
- 맡은 자는 주님께, 그리고 주님이 맡기신 일에 충성되기 위해 기도하고 노력해야 한다.
- 맡은 자를 위해 기도하는 이들은 이들이 주님께 충성을 다하는 삶을 살도록 기도해야 한다.
- 기도없이는 성령님의 도움 없이는 충성된 삶도 없다
- 자책할 것이 없도록 정결하고 충성된 삶을 살지만 이것으로 의롭다함을 얻는 것은 아니며, 그저 받은 은혜로 의롭다함을 얻음과 동시에 받은 은혜의 힘으로 자책할 것이 없는 삶을 살고 있다.
- 이 삶은 주님께서 판단하시고 칭찬하실 것이기 때문에 인간의 칭찬과 정죄는 큰 의미가 없다.
- 아볼로와의 일로 본을 보였으니 서로 교만하여 시기하거나 분열하지 말라. 개개인은 깨달은 것과 삶과 가치관과 신학적 입장이 다를 수 있다. 개인마다 성향과 살아온 삶이 다 다르기 때문이다. 은혜를 주시고 깨닫게 하시는 이의 그 역사로 말미암아 기뻐하며 주님을 높이며 그것을 나누며 더욱 기뻐하며 살아야지, 서로 미워하여 분열하면 안 된다.

9. 적용(나): 
- 기독교 내에서 신학적 입장이 다른 사람을 이해 못할 때가 많았다. 중생 받지 못한 명목적 그리스도인들이 못마땅할 때가 많았다. 그러나 그때 그들도 나를 이해하지 못했을 것이다.  나와 성향이 다르고 살아온 환경이 다르고 생각과 입장이 다르고 전체적인 삶이 다른 사람들을 함부로 판단하지 않겠다. 
- 그저 주 안에서 살아가는 내 모습을 보이며, 주 안에서 살아가는 그들의 모습을 발견하고 또 그런 삶을 기대하며 살아야겠다.
- 지금 내 삶도 받은 은혜로 인한 것이기 때문이다.
- 각자의 삶 속에서 역사하시며, 각자에게 가장 좋은 길을 안내하시는 주님을 기대하며 기도해야 하겠다.

10. 영적터치(단어/구절)  
 7절 네가 받았은즉 어찌하여 받지 아니한 것 같이 자랑하느냐

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

