5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)

-바울은 사랑하는 자녀에게 말하 듯 고린도 성도들에게 자신이 한 행동에 대해 말한다.

-바울은 고린도교회를 위해 디모데를 보내어 권면하고자 했다.

-바울은 주께서 허락한다면 고린도교회를 방문해 자신이 오지 못할 것이라고 말하며 교만해진 사람들의 능력을 확인하고자 했다.

7.하나님 찾기 (해석) 

8.인간(해석):

-바울은 고린도교회 성도들에게 사랑으로 권면했다. 그는 지금 이 시간까지도 굶주리고 목마르고 헐벗고 매맞으며 정처없이 떠돌고, 자신이 직접 일해서 돈을 벌고, 자신에게 욕을 하면 축복해주고, 핍박을 당하면 참고, 비웃고 헐뜯으면 선한 말로 대답했다고 한다. 예수님의 사랑이 없다면 불가능한 일이다. 예수님의 사랑이 있더라도 쉬운 일은 아니다. 바울은 자신을 죽이고 예수 그리스도의 십자가를 날마다 진 것이다. 

9. 적용(나): 


	예수님을 만나고 바보 같은 삶을 살았다. 예전이나 지금이나 예수님을 조금만 이용하면 성직자로 편안한 삶을 살 수 있었을 것이다. 존경받고, 대우받고, 자신을 따르는 사람들에게 왕처럼 굴림할 수 있었을 것이다. 그런데 그런 삶을 살지 않았다. 자신을 현저히 낮추고 오직 예수님의 영광을 드러내기 위한 삶을 살았다. 그로 인해 이 시대에 사는 우리가 바울 통해 귀한 도전을 받을 수 있게 됐다. 



	할 때 사영리 전도지를 불쾌하듯이 피해가거나 거부하는 분들이 계시다. 아무렇지 않을 때가 많지만 가끔은 불쑥 화가 튀어나오기도 한다. 그런데 그럴 때 축복하고 웃으며 선한 말로 끝까지 인사하는 목사님을 보며 대단하단 생각이 든다. 
	욕할 때 축복해주고 무시하거나 핍박할 때 참고, 선한 말을 할 수 있는 사람이 되도록 기도한다. 


