7.하나님 찾기(해석)

8. 인간 찾기 (해석)
바울은 음행하는 자들에 대한 판단과 경고를 기록했다. 우선 교회안에서 음행한자에 대하여 동조하지 말고 철저히 차단하고  분리할것을 당부하고있다. 작은 누룩을 방치하면 전체가 손상을 입듯이 음난한 죄에 대하여 타협하거나 방치하면 공동체 뿐만아니라 자신도 넘어지기게 된다. 그러므로 그러한 행위를 못하도록 처음부터 막아야되며 혹 교회안에 신자는 더욱 그러한 행위를 하지못하도 차단해야한다. 세상의 빛과 소금의 역활을 감당해야 할 하나님의 자녀가 넘어진다는 것은 공동체에서 추방당할 정도로 아픔이 큰것이다 설령 진심으로 회개하고 구원의 연속성에 있더라도 감당하기쉽지 않는 괴로움을 감수하며 살수밖에 없다.  바울은 그러한 음난죄에 대하여 강력한 경각심을 심어주고 있다

9. 적용(나)
평생 음난마귀를 경계하며 넘어지지 않는 종으로 살도록 더욱 영적으로 깨어 있어야겠다.

