INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-10-24', '고린도전서', '6장 11절 ~ 20절', '예수님의 몸의 지체, 그리스도인.', '(고린도전서 6장)
11 너희 중에 이와 같은 자들이 있더니 주 예수 그리스도의 이름과 우리 하나님의 성령 안에서 씻음과 거룩함과 의롭다 하심을 받았느니라
12 모든 것이 내게 가하나 다 유익한 것이 아니요 모든 것이 내게 가하나 내가 무엇에든지 얽매이지 아니하리라
13 음식은 배를 위하여 있고 배는 음식을 위하여 있으나 하나님은 이것 저것을 다 폐하시리라 몸은 음란을 위하여 있지 않고 오직 주를 위하여 있으며 주는 몸을 위하여 계시느니라
14 하나님이 주를 다시 살리셨고 또한 그의 권능으로 우리를 다시 살리시리라
15 너희 몸이 그리스도의 지체인 줄을 알지 못하느냐 내가 그리스도의 지체를 가지고 창녀의 지체를 만들겠느냐 결코 그럴 수 없느니라
16 창녀와 합하는 자는 그와 한 몸인 줄을 알지 못하느냐 일렀으되 둘이 한 육체가 된다 하셨나니
17 주와 합하는 자는 한 영이니라
18 음행을 피하라 사람이 범하는 죄마다 몸 밖에 있거니와 음행하는 자는 자기 몸에 죄를 범하느니라
19 너희 몸은 너희가 하나님께로부터 받은 바 너희 가운데 계신 성령의 전인 줄을 알지 못하느냐 너희는 너희 자신의 것이 아니라
20 값으로 산 것이 되었으니 그런즉 너희 몸으로 하나님께 영광을 돌리라

