4.주제 만들기: 예수님의 몸의 지체, 그리스도인.

5.하나님 찾기 (관찰)
- 하나님이 주를 다시 살리셨음.

6.인간 찾기 (관찰)
- 교인 중 죄를 많이 짓던 자들이 주 예수 그리스도의 이름과 우리 하나님의 성령 안에서 씻음과 거룩함과 의롭다 하심을 받음
- 그리스도인의 몸은 그리스도의 지체임.
- 창녀와 합하는 자는 그와 한 몸이 됨.
- 주와 합하는 자는 한 영이 됨.
- 그리스도인의 몸은 성령의 전이다.
- 그리스도인은 값으로 산 것임.

7.하나님 찾기 (해석) 
- 십자가에서 돌아가신 예수님을 하나님이 다시 살리셨고, 이제 그의 권능으로 그리스도인들도 살리실 것임.

8.인간(해석): 
- 그리스도인은 복음을 믿음으로 성령 안에서 중생을 입었음.
- 그리스도인의 몸은 예수님의 몸의 일부임.
- 창녀와 성행위를 하는 자는 영적으로 창녀와 한 몸이 됨.
- 주와 합하는 자는 주와 한 영이 됨. 그리스도인은 많은 죄악 중에서도 음란은 몸에, 성전에 죄를 범하는 것임을 기억하고 성결하게 살아야 함.
- 그러므로 그리스도인은 주와 합하는 자가 되야 함.
- 그리스도인의 몸은 하나님의 영인 성령님이 거하시는 성전임.
- 그리스도인은 예수님의 십자가 희생의 값, 그의 피 값으로 산 것이니 이를 잘 기억하고 구별된 삶을 살며, 하나님께 영광을 올려드려야 함.

9. 적용(나): 
- 깨어 기도함으로 성령이 거하시는 성전, 즉 내 몸을 거룩하게 관리하며 성령님을 바라보며 예배하는 삶을 살아야 한다.
- 내 몸으로 음행을 즐기는 것이 아니라, 하나님의 영광을 위해 살아가고, 또 하나님의 영광이 되는 것을 즐거워하며 살아야 한다.

