4.주제만들기 : 하나님께서 주신 선물을 유혹으로 사용하는 사탄
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 결혼과 관계된 문제들에 대하여 이야기 한다.
- 바울은 남편과 아내로서 의무를 다하며 존중하도록 말한다.
- 바울은 부부 관계에서 사탄이 유혹할 수 있음을 경고한다.
- 결혼하지 않은 사람은 혼자 지내는 것이 유익하고, 정욕을 다스리지 못하면 결혼하는 것이 낫다고 말한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 결혼 관계에서 남편과 아내가 서로의 의무를 다하지 않으면 사탄이 유혹하여 넘어질 수 있다고 경고한다. 하나님께서 주신 선물을 틈타 쾌락의 도구로 사용하려는 육체적 욕망을 경고하고 있다. 
- 또한 혼자인 경우 정욕을 다스리지 못할 경우 결혼하는 것을 권하며 사탄에게 틈을 주지 말도록 하고 있다. 
9. 적용(나): 
- 하나님께서 주신 선물은 자신의 욕구를 만족시키는 쾌락의 도구로 사용해선 안 된다. 특히 부부관계를 넘어서는 유혹을 무시해서는 안 된다. 그러기 위해선 오직 예수 그리스도만 의지하고 성령님의 도우심을 쫓아 살아야 한다. 
- 사탄은 늘 우리를 무너뜨리려는 것을 인식하고 사탄이 틈타지 않도록 말씀과 기도로 이겨낼 수 있도록 단련시켜야겠다.
10. 영적터치(단어/구절)
- 너희가 절제 못함으로 말미암아 사탄이 너희를 시험하지 못하게 하려 함이라
