8. 인간 찾기 (해석)
바울은 진정한 자유를 누릴것을 권면하고있다. 그러기위해서는 철저히 주의 종이 됐을때에만이 가능하다. 세상의 종으로 살면 진정한 자유를 가질수없다. 자유를 가졌다고 하더라도 결혼후에는 고난도 자연스럽게 동반된다. 물론 고난을 감수하더라도 결혼은 누구나 선택할 자유가 있다고 바울은 말한다. 그럼에도 바울은 특별한 때(환난)는 가급적이면 결혹보다는 홀로 지내는것이 좋다고 기록하였다

