바울은 결혼에 대한 사람들이 이땅에서 누릴수있는 자유에 대하여 설명하고 있다. 결혼은 해도 좋고  늦게해도 좋고 때로는 미망인이 되었더라도 또다시 재혼도 주님께서 허용하신다고 말한다. 그럼에도 바울은 가급적 과부된사람은 홀로 지내면서 주님을 섬기는 일을 하는 사람은 더욱 복된삶을 사는 사람이라 지도하고 있다. 바울은 결혼의 행사보다 즉 가정을 이루는 가장 근본적인 목적은 주님을 잘 섬김이라 강조하고 있다.

