우상제물에 대한 양심

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
우상의 제물을 먹는 사람들에 대한 바울의 생각

7.하나님 찾기(해석)

8. 인간 찾기 (해석)
바울은 우상의 제물을 먹는 문제에 대하여 명확하게 정리하였다. 우선 우상 제물을 먹는것은 죄에 해당되지 않는다. 우상에게 제사를 하는 행위는 큰 죄에 해당하지만 음식 자체만으로는 믿는 자들에게는 영향을 미칠수없다. 다만 그음식을 우상시 하며 먹는 사람은 죄에 해당된다. 즉 음식을 먹는지 아닌지에 따라서 정해지는것이 아니라 믿음에 관계되는 문제인것이다. 다만 신앙인이 우상제물을 먹는다고 죄에 해당되지는 않지만 바울은 가급적 피하라고 권면한다. 이유는 믿음이 아직 약한이들이 먹는 모습을 보고 실족될수 있기때문이다.

9. 적용(나)
하나님이 주신 자유도 영혼구원 을 위하여 지혜롭고 덕스럽게 사용하여야겠다.

