8. 인간 찾기 (해석)
사도인 바울은 사도로써 얼아든지 누릴수 있는 자유를 설명하고 있다. 먹고 마실수 있는 권리, 베드로(게바)처럼 아내를 사역현장에 데리고 다닐 권리등 을 예로 들고있다. 그럼에도 바울은 진정한 주님안에서의 자유는 누릴수 있는 권한을  절제하며 복음을 위하여 참는것이 진정한 자유임을 느끼게 하고있다. 자신에게 처해진 쉽지않는 환경을 받아들이고 자족하며 다른 사역자와 비교하지않고 묵묵히 받은 사명을 감당하고자 하는 바울의 태도를 알수있다.

9. 적용(나)
주를 위한 절제된 자유를 누리는 종이 되야겠다 

