8. 인간 찾기 (해석)
복음자요 사도인 바울은 오직 주님의 영광만을 올리는 정말 신실한 종이다. 그러한 이유는 바울은 복음을 전파한후 스스로에게 올수있는 자랑 하고자 하는 마음을 철저히 경계하고 있다.  또한 많은 영혼들이 주님께 돌아올수 있도록 스스로를 겸비하여 종의 자세로 사람들에게 다가가 복음을 전파하는 성품을 볼수있다. 복음의 유연성으로 만나는 민족이나 다른 사상을 가지고 있는사람들에게 오직 복음의 진리 외에만  맞춤형으로 복음을 전파하는 지혜를 알수있다.

9. 적용(나)
복음전파시 종의 자세로 더욱 많은 영혼들에게 주의 말씀을 나누어야겠다

