- 
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 율법 없는 자에게 율법 없는 자처럼, 약한 자에게 약한 자와 같이 여러 모습으로 복음을 전하고 구원하고자 노력함
- 바울은 복음에 참여하여 썩지 아니할 것을 위해 절제하고 목표를 향해 달려가며 이기기 위해 싸우며, 자신의 몸을 쳐 복종시켜 복음 전파를 하여 자신이 버림받지 않도록 한다고 말함.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 한 영혼을 소중히 여겼다. 그렇기에 그가 가진 문화, 특성을 이해하고 그에 맞는 행동을 통해 복음을 전하고자 노력했다. 
- 바울은 특히 절제를 강조했는데 분명한 목표가 있기에 어려운 싸움을 할 준비가 되어 있고 자신을 낮추어 복음 전파를 하였다.
9. 적용(나):
- 복음을 전하는 것은 어려운 일이다. 나와 다른 사람에게 나의 관점에서 복음을 전하는 것은 다른 사람의 입장에서 받아들이기 어려울 것이다. 그렇기에 자신을 낮추지 않으면 복음을 전하기 매우 어렵다. 
- 다른 사람의 입장에서 문화와 특성을 따라 행동하는 것은 나를 복종시키지 않으면 불가능한 일이다. 그렇기에 바울은 자신의 몸을 쳐서라도 복음을 전하려고 한 것이다. 그만큼 내 안에 나는 죽고 예수 그리스도만 들어나는 삶을 살도록 노력해야 한다.
- 나 자신을 낮추고 겸손한 자세로 사역에 임해야겠다. 
