2023년 11월 17일 고린도전서 10장 21절~33절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 주의(22절), 귀신의(22절), 겸하여(22절), 가하나(23절), 유익(23,24,33절), 양심(27,28,29절), 감사(30절), 구하다(33절)
4.주제만들기: 하나님을 믿지 않는 사람에게 시험이 되는 존재가 되어서는 안 된다.
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 자신의 유익을 바라지 말고 다른 사람의 유익을 바라라고 말한다. 
- 시장에서 파는 음식은 어떤 것이든 양심에 거리낌이 생기지 않도록 묻지 말고 먹으라고 하였으며, 믿지 않는 사람이 초대했을 때 가기 원한다면 준비된 음식을 양심에 거리낌 없이 먹으라고 말한다. 단, 우상에게 바쳐진 제물이라고 말한다면 준 사람과 양심을 위해 먹지 말라고 권면한다.
- 먹든지 마시든지 무엇을 행하든지 모든 것을 하나님의 영광을 위해 행하라고 권한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 하나님을 믿지 않는 사람과의 교제에서 믿는 사람이 취해야할 행동에 대해 강조하는데 그것은 믿는 사람으로 인해 믿지 않는 사람이 시험에 들 수 있기 때문에다. 믿는 사람으로서의 행동이 믿지 않는 사람과 함께할 때 믿지 않는 사람처럼 행동하는 것들이 참 많다. 그럴 때 모든 일을 하나님의 영광을 위해 행하라는 말로 도전을 준다.
9. 적용(나): 
- 믿지 않는 사람들이 교회를 배척하는 가장 큰 이유 중 하나는 크리스천이 행하는 모습으로 인해 상처받은 경험 때문이다. 최근 고등학교 친구를 만나서 어렸을 때 내 중심적으로 행동하고 말했던 것에 사과를 했다. 그 친구에게 사과할 수 있어서 얼마나 감사한지 모르겠다. 
- 그런데 나로 인해 상처받은 친구들이 많았을거라 생각하니 끔직하다. 미안하고 후회된다. 친구들에게 달라진 모습을 보여주어 진심으로 사과하고 하나님의 영광이 드러나도록 행동해야겠다.
- 가정, 직장, 교회, NKFC 등 모든 곳에서 하나님의 영광이 드러나도록 기도해야겠다. 
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-11-05', '고린도전서', '11장 1절 ~ 10절', '제목 없음', '(고린도전서 11장)
1. 내가 그리스도를 본받는 자가 된 것 같이 너희는 나를 본받는 자가 되라
2.  너희가 모든 일에 나를 기억하고 또 내가 너희에게 전하여 준 대로 그 전통을 너희가 지키므로 너희를 칭찬하노라
3. 그러나 나는 너희가 알기를 원하노니 각 남자의 머리는 그리스도요 여자의 머리는 남자요 그리스도의 머리는 하나님이시라
4. 무릇 남자로서 머리에 무엇을 쓰고 기도나 예언을 하는 자는 그 머리를 욕되게 하는 것이요
5. 무릇 여자로서 머리에 쓴 것을 벗고 기도나 예언을 하는 자는 그 머리를 욕되게 하는 것이니 이는 머리를 민 것과 다름이 없음이라
6. 만일 여자가 머리를 가리지 않거든 깎을 것이요 만일 깎거나 미는 것이 여자에게 부끄러움이 되거든 가릴지니라
7. 남자는 하나님의 형상과 영광이니 그 머리를 마땅히 가리지 않거니와 여자는 남자의 영광이니라
8. 남자가 여자에게서 난 것이 아니요 여자가 남자에게서 났으며
9. 또 남자가 여자를 위하여 지음을 받지 아니하고 여자가 남자를 위하여 지음을 받은 것이니
10. 그러므로 여자는 천사들로 말미암아 권세 아래에 있는 표를 그 머리 위에 둘지니라

