그리스도를 본 받는 바울
가정의 머리되신 그리스도

7.하나님 찾기(해석)

8. 인간 찾기 (해석)
바울은 자신을 향해 본을 삼으라고 말한다. 얼핏보면 스스로를 영적 거장 이라는 느낌을 줄수있다.
하지만 내용을 자세히 보면 바울의  의중은 분명한것을 알수있다. 1절에 "내가 그리스도를 본받는 자가 된 것 같이" 라고 기록한것은 자신을 기준 삼지말고 오직 주님을 본받으라는 것을 강조하고 있다. 물론 사도바울은 모든사람들이 충분히 본받을만한 사람이다. 그럼에도 바울은 결코 스스로를 높이지 않고 오직 주님만 높이는데 주력한다. 부부 관계에서도 마찬가지 비유를 사용하고 있다.
남편의 머리는 하나님 이고 아내의 머리는 남편이라 되어 있지만 남자가 여자를 다스리는 수직 관계가 아닌  모든 가정의 머리되신 하나니을 강조하는 것이다. 오직 하나님을 사랑하고 부부와 형제 자매를 포함한 이웃을 사랑하라 하신 아버지의 마음을 비유적으로 설명하는 바울의모습을 볼수있다.

9. 적용(나)
그리스도를 더욱 나의 인생의 기준으로 삼고 살아내야겠다 

10. 영적 터치(단어/구절)
1절: 내가 그리스도를 본받는 자가 된 것 같이

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

