8. 인간 찾기 (해석)
남자 와 여자의 근본적인 출생은 최초로 인간을 창조하신 오직 하나님 이심을 바울은 상기시키고 있다. 또한 바울이 활동했던  당시 극동지역 에서는 여자가 기도 할때 머리를 가리는 관례가 있었다. 이로 인하여 교회안에 논쟁이 생겨 바울은 이러한 불필요한 논쟁을 해결하고자 그러한 관례가 교회의 본질적 행위가 아니라는 것을 가르치고 있다. 
한편 주의 만찬을 먹을때에도 분쟁이나 파당하는 마음으로 참여하지 말것을 당부하고있다. 성만찬의  본질에서 벗어났기 때문이다.
바울은 인간들은 언제든지  자신들의 높아짐을 쉽게 가질수 있음을 경계시키고 있다.
주님의 순수한 사랑에서 벗어나 다양한 관례등을 만듬으로 나름대로 세련되고 절도있는 품의를 지키는 것처럼 보이지만 자칫 잘못하면 그것이 올무가 될수 있음을 바울은 간접적으로 알려주고 있다. 

