8. 인간 찾기 (해석)
바울은 성만찬의 의미를 드러내고 있다. 예수님의 몸이 찢기시고 피를 흘리셨던 사랑을 기억하며 행히는 영적의식이라 말하고 있다.
의식을 치루는 성도의 태도로는 화합과 사랑의 정신을 내포하고 있다. 또한 성만찬 의식을 치루는 성도는 예수님의 숭고한 희생과 사랑이다. 이 정신을 가지고 주님의 사랑안에서 형재애를 갖는다면 올바른 영적 의식을 행하는 사람이라 여긴다고 바울은 강조하고 있다. 반면 피의 언약과 예수님의 몸을 상징하는 떡의 의미를 분별하지 못하고 행하는 자는 죄짓는 자라 여김을 받는다고 바울은 말한다. 피로세운  언약은 주님의 사랑과 희생가운데 그뜻을 기억하며 한 몸이라는 것을 기억하고 믿는 의식이다.

