4.주제만들기: 같은 성령으로 하나되는 성도
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 성령의 은사에 대해 모르는 것을 원하지 않는다고 말함.
- 은사는 여러 가지이지만 성령은 같고, 직분과 임무는 여러 가지이지만 섬기는 주는 같다고 말함. 
- 각 사람에게 성령을 나타내시는 것은 우리를 유익하게 하려 하신다고 말함.
7.하나님 찾기 (해석) 
8.인간(해석):
- 당시 고린도교회를 생각하면 복음을 강력하게 뻗어나갔지만 현대와 같이 성도를 이끄는 사역자의 부재와 성경을 알지 못하는 것들로 인해 많은 어려움이 있었을거라 생각한다. 이 때 바울은 성령을 강조하며 성도들에게 권면한다. 
- 성령은 모든 상황을 하나님의 뜻으로 인도하시기 때문에 은사가 다르더라도 서로를 인정할 수 있게 되고 직분의 차이가 있더라도 높은 자가 낮은 자를 존중하고 낮은 자는 높은 자를 존경할 수 있는 마음을 얻게 한다. 성령이 없이 성도의 생각과 뜻대로 행동한다면 교회가 어려워질 수 있다는 점을 바울은 안 것이다.
9. 적용(나): 
- NKFC안에서 늘 주의해야 할 부분인데 하나님의 뜻보다 내가 앞서려는 교만한 행동을 할 때가 참 많다. 또한 과거에 축구를 했다는 이유로 다른 사람의 의견을 쉽게 생각하거나 무시할 확률도 매우 높다. 그렇지만 성령을 의지하고 성령과 동행하며 성령의 뜻 가운데 행동한다면 나의 교만함을 억제할 수 있을 것이다. 
- 내가 남보다 낫다는 생각을 버리고 낮은 자세로 주님의 뜻만 바라보도록 기도해야겠다. 
- NKFC라는 공동체를 형성할 수 있음에 감사드린다. 각자 맡을 수 있는 임무와 은사가 다르기 때문에 서로 의지할 수 있다. 어느새 NKFC의 리더가 된 대한이와 성균이를 내가 많이 의지하고 있다는 것을 느낀다. 대한이와 성균이를 서포트할 수 있는 리더들이 새워지도록 기도해야겠다.
