6.인간 찾기(관찰)
각 지체로 부름을 받은 자녀들

7.하나님 찾기(해석)
몸 되신 그리스도께서 그의 자녀들을 각자 다른 은사와 역활을 주셨다. 나무에 븉어 있는 가지처럼 각자 모습은 다르지만 결국 햔 성령  즉 예수그리스도 몸에 있는 한 운명 공동체인것을 하나님은 바울을 통하여 깨우치게 하신다.
8. 인간 찾기 (해석)
사람의 몸의 한 부분인 코와 귀가 다르더라도 각각 신체에 꼭 필요한 요소들이다. 이런것처럼 성도 각자는 은사와 역활은 비록 다르지만 그리스도 안에서 햔 지체인것을 깨우치고 서로를 인정하고 소중히 여길것에 대하여 깨우침을 주고 있다
그러므로 성도들은 경쟁 대상이 아닌 서로 섬기고 감사할 존재들이다

9. 적용(나)
내가 만나는 NKFC 지체들을 더욱 소중하게 여기며 사랑해야겠다.

