2023년 11월23일 고린도전서 12장 21절~31절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-지체(22,23,24,25,26,27절), 몸(22,23,24,25,27절)
4.주제만들기; 
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 성도들의 연합을 강조하며 몸으로 각 지체의 중요성에 대해 강조하고 있다.
- 바울은 더 약해보이는 몸의 지체들이 중요하다고 강조한다.
- 성도는 그리스도의 몸이고 그 몸의 지체라고 말한다. 
- 하나님께서 교회에 몇가지 은사를 주셨고 각 역할이 다르니 더 큰 은사를 위해 간구하라고 말한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 몸에서 아름답지 못한 곳을 더 귀한 것들로 입혀주어 귀중함을 더한다고 말한다. 예를들자면 눈, 머리, 손, 발은 우리의 일상생활에 중요한 역할을 하지만 옷에 가려진 지체는 덜 중요하게 여길 수 있다. 그러한 몸에 아름다운 옷을 입으면 사람들의 시선은 그 사람 눈, 머리, 손, 발이 아닌 아름다운 옷에 집중하게 된다. 
- 이렇듯 바울은 성도가 서로의 연약함을 채우면 아름다운 옷을 입은 것처럼 빛나게 할 수 있는 존재임을 알려주었다. 
- 이는 교회에 생길 수 있는 계급을 막고 겸손과 존중으로 서로 연합하도록 할 수 있는 동력이 되었을 것이다.   
9. 적용(나): 
- 아름다운 옷으로 아름답지 못한 부분을 더욱 아름답게 할 수 있는 겸손함과 시기 질투가 없는 마음이 내 안에 가득하길 원한다. 
- 특히 공동체에서 누군가가 어려움이 있을 때 함께 가슴 아파할 수 있는 마음과 누군가의 기쁨을 진심으로 즐거워하며 하나님께 영광돌릴 수 있는 넓은 마음을 갖도록 기도한다.
- 마지막으로 하나님께서 주시는 은사를 사모해야겠다.
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-11-11', '고린도전서', '13장 1절 ~ 13절', '진짜 사랑이란?', '[고전13:1-13]
1 내가 사람의 방언과 천사의 말을 할지라도 사랑이 없으면 소리 나는 구리와 울리는 꽹과리가 되고
2 내가 예언하는 능력이 있어 모든 비밀과 모든 지식을 알고 또 산을 옮길 만한 모든 믿음이 있을지라도 사랑이 없으면 내가 아무 것도 아니요
3 내가 내게 있는 모든 것으로 구제하고 또 내 몸을 불사르게 내줄지라도 사랑이 없으면 내게 아무 유익이 없느니라
4 사랑은 오래 참고 사랑은 온유하며 시기하지 아니하며 사랑은 자랑하지 아니하며 교만하지 아니하며
5 무례히 행하지 아니하며 자기의 유익을 구하지 아니하며 성내지 아니하며 악한 것을 생각하지 아니하며
6 불의를 기뻐하지 아니하며 진리와 함께 기뻐하고
7 모든 것을 참으며 모든 것을 믿으며 모든 것을 바라며 모든 것을 견디느니라
8 사랑은 언제까지나 떨어지지 아니하되 예언도 폐하고 방언도 그치고 지식도 폐하리라
9 우리는 부분적으로 알고 부분적으로 예언하니
10 온전한 것이 올 때에는 부분적으로 하던 것이 폐하리라
11 내가 어렸을 때에는 말하는 것이 어린 아이와 같고 깨닫는 것이 어린 아이와 같고 생각하는 것이 어린 아이와 같다가 장성한 사람이 되어서는 어린 아이의 일을 버렸노라
12 우리가 지금은 거울로 보는 것 같이 희미하나 그 때에는 얼굴과 얼굴을 대하여 볼 것이요 지금은 내가 부분적으로 아나 그 때에는 주께서 나를 아신 것 같이 내가 온전히 알리라
13 그런즉 믿음, 소망, 사랑, 이 세 가지는 항상 있을 것인데 그 중의 제일은 사랑이라

