2023년 11월 24일 고린도전서 13장 1절~13절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기: 진짜 사랑이란?
5.하나님 찾기 (관찰)
-사랑(1,2,3,4,8,13절), 부분적으로(9,10절), 어린 아이와 같이(11절)
6.인간 찾기 (관찰)
- 바울은 어떠한 은사가 있더라도 사랑이 함께하지 않으면 쓸모 없다고 말한다. 
- 바울은 사랑이 가진 능력에 대해 설명한다. 
- 바울은 우리가 가진 은사는 언젠가는 사라지지만 믿음, 소망, 사랑은 언제까지나 남아있으며, 그 중 가장 위대한 것은 사랑이라고 말한다.
7.하나님 찾기 (해석) 
8.인간(해석):
-바울은 하나님께서 우리를 사랑하셔서 독생자를 보내신 그 사랑을 정확히 깨달았다. 그렇기 때문에 대인관계에서 상대방의 신분이 높든 낮든, 지식이 있든 없든, 신앙이 있든 없든 간에 사랑으로 모든 사람을 대했다. 
-복음을 전하며 수많은 믿지 않는자부터 믿는자에게까지 수많은 고초를 겪었을테인데 진짜 사랑을 깨달은 바울은 그 많은 고초를 이겨낼 동력을 가지고 있었을 것이다. 자신이 경험한 사랑의 능력을 많은 성도들이 깨닫길 원한 것 같다.
9. 적용(나): 
- 사랑은 내가 좋아하는 사람들에게만 적용되는 것이 아니라 오늘 당장 처음 만난 사람이라도 사랑을 가지고 대하여야 한다. 세상 기준으로 너무 바보 같은 선택이지만, 짧은 경험을 비추어 볼 때 사랑을 품고 행동할 때 결국 상대방은 그 사람의 진심을 깨닫게 된다. 깨닫는 기간은 저마다 다르기에 내 자신을 한 없이 낮추어야 한다.
- 예수님을 통해 거듭난 육체는 사랑을 실천하고자 하지만 이전의 육체는 세상 기준으로 손해보는 행동을 하지 못하는 제약을 건다. 그저 예수님의 사랑을 실천하는 바보같이 살고 싶다. 오늘도 나는 죽고 예수님이 내 안에 사시는 삶을 간절히 바래본다. 
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-11-12', '고린도전서', '14장 1절 ~ 10절', '제목 없음', '(고린도전서 14장)
1.  사랑을 추구하며 신령한 것들을 사모하되 특별히 예언을 하려고 하라
2. 방언을 말하는 자는 사람에게 하지 아니하고 하나님께 하나니 이는 알아 듣는 자가 없고 영으로 비밀을 말함이라
3. 그러나 예언하는 자는 사람에게 말하여 덕을 세우며 권면하며 위로하는 것이요
4. 방언을 말하는 자는 자기의 덕을 세우고 예언하는 자는 교회의 덕을 세우나니
5. 나는 너희가 다 방언 말하기를 원하나 특별히 예언하기를 원하노라 만일 방언을 말하는 자가 통역하여 교회의 덕을 세우지 아니하면 예언하는 자만 못하니라
6. 그런즉 형제들아 내가 너희에게 나아가서 방언으로 말하고 계시나 지식이나 예언이나 가르치는 것으로 말하지 아니하면 너희에게 무엇이 유익하리요
7. 혹 피리나 거문고와 같이 생명 없는 것이 소리를 낼 때에 그 음의 분별을 나타내지 아니하면 피리 부는 것인지 거문고 타는 것인지 어찌 알게 되리요
8. 만일 나팔이 분명하지 못한 소리를 내면 누가 전투를 준비하리요
9. 이와 같이 너희도 혀로써 알아 듣기 쉬운 말을 하지 아니하면 그 말하는 것을 어찌 알리요 이는 허공에다 말하는 것이라
10. 이같이 세상에 소리의 종류가 많으나 뜻 없는 소리는 없나니

