4. 주제 만들기 
방언과 예언의 목적

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
방언은 자신의 덕을 세우며 예언은 교회의 덕을 세우는데 목적이 있다

7.하나님 찾기(해석)
하나님은 신자들에게 방언의 은사와  예언의 은사를 주셨다. 방언은 자신의 덕을 위하여 예언은 교회의 덕을 세우기 위함이다.
8. 인간 찾기 (해석)
하나님으로부터 받은 방언의 은사와 예언의 은사들은 다른사람들에게 돋보이기위한 과시용으로 사용되어서는 안된다.
특징으로는 방언은 기도할 때 깊은대화를 오랫동안 할수있다. 예언의 은사는 특별히 계시의 은사를 받은 사람이기 때문에 반드시 교회가 올바른 방향대로 갈 수 있도록 조언을 잘 해야한다. 교회에 덕을 세우고 하나님의 영광을 올려야할 막중한 위치임을 바울은 일깨워주고 있다

9. 적용(나)
받은 방언은사를 지혜롭고 덕스럽게 잘 사용해야겠다.

10. 영적 터치(단어/구절)
