2023년 11월27일 고린도전서 14장21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
방언: 21, 22, 23, 26, 27  
믿는 자: 22(2)
믿지 아니하는 자: 22(2), 23, 24
알지 못하는 자: 23, 24
