4. 주제 만들기: 은사를 바라고 즐거워하되, 질서 있게 사용하라.

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
방언은 믿지 아니하는 자들을 위하는 표적, 예언은 믿는 자들을 위한 것.
믿지 않는 자들이 예언을 듣게 되면 하나님이 참으로 너희 가운데 계신다 전파할 것이다.
공개적인 방언은 통역할 사람이 있을 때 하는 것이다.
예언은 둘이나 세명이 말하고 다른 이들은 분별해야 한다.


7. 하나님 찾기(해석)

8. 인간 찾기 (해석)
교회의 덕을 위해서는 공개적인 방언을 절제하고 예언을 하는 것이 좋다. 
통역하는 사람이 없을 때는 하나님과 자기만 들리게 조용히 하거나 골방에서 하거나 집에서 하는 것이 덕을 세우는 데 좋다.
사람의 예언은 부분적이고 불완전하므로 첫째, 한 명보다는 두 명 이상이 하는 것이 예언을 듣고 하나님의 뜻을 분별하는데 더 좋을 것이다. 둘째, 믿음 있는 자들이 듣고 이 예언이 하나님께로부터 온 것인지 분별하고 그것이 맞다면 그 뜻을 어떻게 순종해야 하는지 지혜를 구하고 순종을 위해 기도해야 한다.

9. 적용(나)
- 방언도 통역(통변)도 예언도 모두 하나님께서 주신 선물이다. 각자에게 맞는 선물을 한 성령님께서 주시는데, 이 선물을 감사함으로 받고 개인과 교회의 덕을 위해 성실히 사용해야 한다. 
- 하나님께서는 예수님의 부활 승천 이후, 이 시대에는 하나님의 뜻하심에 따라 예수님을 통해 성령님의 임재하심, 내주해 주심, 인도하심의 은혜와 함께 은혜의 선물인 은사를 주셨고, 지금도 계속하여 주고 계신다. 받는 이들은 두려워하지 말고 놀라움과 감사함과 더불어 겸손함으로 받고, 하나님께 영광을 올려드리며 이것을 개인과 교회를 위해 사용해야 한다. 
- 방언을 못 알아듣는다고 안 하거나, 바쁘다고 방언 기도를 안 하는 것은 선물을 받았을 때의 놀라움과 기쁨과 경이로움과 감사함을 잊는 처사이다. 방언 기도를 함으로써 개인의 덕과 영적 능력을 갈고닦아야 한다.
- 통역을 위해 개인과 교회가 함께 기도해야 한다. 통역은 교회 전체에 덕을 세우는 일이기 떄문이다. 하나님은 개인만이 아니라 교회 모두가 하나님의 비밀을 알기를 원하시고 그 원하시는 뜻을 알리기 위해 통역을 사용하신다.
- 예언을 사모함으로 간절히 기도해야 한다. 이 예언은 불신자들이 예수님을 믿는 데 도움이 된다.
- 받은 은사에 감사하며 하나님의 영광과 하나님 나라의 덕과 확장을 위해 꾸준히 성실히, 그리고 질서 있게 사용해야 한다. 
- 덧붙이고 싶은 말은 자기에게 드러나는 은사가 없다고 해서 은사 받은 사람은 가짜라고, 성령님은 이 시대에 그렇게 역사하지 않는다고 함부로 판단하고 비난해서는 안 된다. 모 교단의 몇 사람들이 성령의 계시와 은사는 끝났다고 주장하는데, 그것은 옳은 주장이 아니다. 하나님을 사랑하는 사람들이 서로를 사랑해야지 나와 다르다고 비난해서는 안 된다. 예수님을 믿는다면 서로 사랑하는 것이 마땅하다. 

10. 영적 터치(단어/구절)
26 너희가 모일 때에 각각 찬송시도 있으며 가르치는 말씀도 있으며 계시도 있으며 방언도 있으며 통역함도 있나니 모든 것을 덕을 세우기 위하여 하라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

