2023년 11월 28일 고린도전서 14장 31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기 : 은사로 만드는 조화로운 예배
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 예언하는 자들은 계시를 받을 때 한 사람씩 말하도록 했고 예언하는 자들은 예언하는 사람들에 의해 통제를 받을 것이라고 말했다.
- 바울은 교회에서 여성도는 말을 하지 않도록 했으며, 궁금함이 있다면 가정에서 남편에게 물어보도록 권했다. 
- 바울은 예언을 건잘히 사모하고, 방언하기를 금하지 말라고 하였으며, 모든 일을 적절하고 질서있게 하도록 권면했다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 은사를 받은 성도들이 은사로 인해서 자칫 예배의 질서를 흐트러 뜨릴 수 있다는 것을 알았다. 은사를 받은 각 성도들이 자신의 은사를 강조하며 예배의 본질을 무너뜨릴 수 있기에 은사를 은사의 목적과 장소, 상황에 맞게 사용하도록 안내했다.
9. 적용(나): 
- 은사를 나의 권위를 높이기 위해 사용해서는 안 된다. 은사를 지혜롭게 사용해야겠다. 
- 은사를 사모하는 기도를 해야겠다. 그리고 은사를 받았을 때 겸손함을 가지고 자신을 낮추는데 사용하도록 훈련해야겠다.
