8. 인간 찾기 (해석)
바울이 그리스도를 만난이후의 삶은 은혜와 겸손의 삶인것을 알수있다.
주님께 부르심을 받은 이후에 그가 경험한 모든 고난의 수고를 불평 하기보다는 도리어 하나님의 은혜로 승화하는 모습을 볼수있다. 보통 하나님 일 하다가 고난을 받게되면 하나님께 불편한 마음을 보이는 것이 일반적일 것이다. 그러나 바울은 사도중의 가장 작은 사도로 스스로를 여겼다. 뿐만아니라 그는 과거에 교회를 박해 하였던  자신을 용서하신 부활의 예수의 사랑으로 쓰임받게 된것 자체로 기뻐하며 겸손한  모습을 나타내고 있다. 진정한 은혜롭게 사는 신앙인이 모습을 바울은 보여주고 있다. 
바울은 과거의 자신의 영적가시(성도를 핍박함)를 늘 품으며 더욱 겸손한 마음을 지켰던것 같다 

