-바울은 부활에 대해 말하며 마지막 나팔 소리에 변화될 것이라고 말한다.

-죽은 자들이 썩지 아니할 것으로 살아나고, 썩을 것이 썩지 아니할 것을 입고, 죽을 것이 죽지 아니함을 입는다고 말한다. 

-바울은 견실하여 흔들리지 말고 항상 주의 일에 힘쓰는 자들이 되라고 강조하며 우리의 수고가 주안에 헛되지 않다고 말한다.

7.하나님 찾기 (해석) 

8.인간(해석):

-당시 성도들이 바라던 이상과 현실은 너무 달랐을 것이다. 계속되는 핍박과 고난, 교회 안에서의 문제, 성경의 잘못된 해석으로 이단화 등등 예수님을 믿는 자들은 끊임없이 외부의 문제와 내부(자신)의 문제에 부딪히고 있었다. 바울은 성도들에게 용기와 희망을 주고자했다. 부활이 있고 사망을 이기는 승리를 쟁취하도록 격려했다. 

9. 적용(나): 

-당시의 상황보다 너무 좋은 환경에 있는 나도 내외부적인 문제로 갈등을 할 때가 많다. 그러나 그 때마다 견실해야하며 주의 일에 더욱 힘쓰는 자가 되어야겠다. 어려운 상황일수록 주님을 더욱 의지하는 견고한 믿음이 세워지기 바란다.

-앞길이 보이지 않고 캄캄할 때 주님을 의지하여 믿음의 눈으로 세상을 바라보는 지혜가 있길 소망한다.

