-바울은 고린도교회 방문을 희망하는데 그보다 에베소에서 사역할 일을 먼저 생각한다. 그리고 자신을 대신해 디모데를 고린도교회로 보내며 디모데를 자신과 같이 돌보아주도록 당부한다.
