8.인간(해석):
-바울은 자신의 방문이 고린도교회에 큰 힘이 될 것을 알고 있다. 하지만 자신이 하고 있는 사역에 집중하여야 하기 때문에 자신을 대신해 디모데를 보낸다. 사도 바울이 직접 고린도교회에 방문하는 것이 고린도교회에 좋은 일이 될 수 있지만 어쩌면 바울을 맹신하거나 바울만을 의지하는 역효과가 나타날 수 있다. 바울은 자신을 대신해 디모데를 섬기게 함으로써 고린도교회 성도들의 영적 성장을 생각했던 것 같다.
9. 적용(나): 
