하나님은 모든 환난 중에 있는 자녀들을 크게 위로하시고 구원하실수 있는 능력의 아버지이시다. 뿐만 아니라 살 소망까지 보이지 않는 자녀들에게 살 소망도  주시고 죽은자 조차도 살리시는 능력자이시다. 모든 고통을 아시고 다시소생시킬수 있는것은 그분 스스로가 먼저 독생자예수를 통하여 큰 고난을 경험하셨기 때문이다.
