8. 인간 찾기(해석)
하나님은 모세를 통하여 돌판에 새긴 율법을 이스라엘 백성들에게 허락하셨다. 그 율법을 통하여 인간과 하나님과의  약속을 지키고 또한 수용하는 친밀 관계가 형성되었다. 이후에 이스라엘 백성들의 반복되는 죄로인하여 또 다시 인간과 하나님간의 관계가 멀어져 갈 쯤 하나님은 결단을 하셨다. 율법보다 더 강력한 친밀감을 그분의 헌신의 사랑을 인간들에게 보여주셨다. 즉 신자들의 마음에 그리스도의 편지를 쓰신것이다. 물론 바울은 하나님이 인간을 향한 의와 사랑의 친밀감이 얼마다 강렬한지를 비유적으로 표현 한 것이다. 그래서 바울은 그리스도의 편지라고 표현했다. 이제는 돌에 새기고 부서지고 할 수 없는 견고하고 단단한 그리스도의 사랑의 마음을 믿는자는 결코 정죄받는것이 아니라  하나님의 영광의 직분을 이미 가진 자 라고 강조 하고있다.

9. 적용(나)
마음에 새겨진 아버지의 마음을 알고 매순간 성령하나님과 깊은 관계를 더욱 세워야겠다.

