-바울은 담대히 말했다
-모세가 하나님의 영광으로 자신을 주목하게 될까 수건으로 얼굴을 가린 것과는 다르게 이스라엘 자손들은 마음이 완고해져 수건을 벗지 못하고 있다고 함
-주께로 돌아가면 수건이 벗겨지고 주의 영이 계신 곳에 자유가 있다고 말함.
7.하나님 찾기 (해석) 
8.인간(해석):
-모세는 하나님의 영광이 자신에게 쏠릴 것을 염려해 얼굴을 가렸다. 반면 이스라엘 백성은 하나님의 영광이 가려지도록 수건을 덮었다. 인간의 완악함을 볼 수 있는데 같은 수건이어도 하나님의 영광을 나타내기 위해 사용할 수도 있고 하나님의 영광을 덮어버리는데 사용할 수 있다. 
-하나님의 영광을 덮어버리는데 사용한 수건은 주께로 돌아가야 벗겨질 수 있다. 주의 영이 계신 곳에 자유가 있는데, 영이신 주님께서 언제든 우리를 맞이할 준비를 하고 계신 것이다. 주님의 영이 아니시라면 우리는 누군가로 인해 회복되어야 하고 누군가로 인해 구원을 받아야 하지만 영이신 주님을 통해 입술의 고백만으로 구원을 받고 죄에서 벗어날 기회를 얻게 된 것이다.
9. 적용(나):
-나의 얼굴에 자신의 영광을 가리기 위한 수건이 아닌 하나님의 영광을 가리기 위해 덮은 수건을 예수님의 사랑으로 벗겨지길 원한다. 매번 반복되지만 죄에서 자유로워지길 간절히 소망한다. 남은 삶은 주님과 깊은 교제로 살아가고 싶다.  
