7.하나님 찾기 (해석)
보배 되시고 생명되시는 예수를 붙잡고 사는 사람은 결코 실패자가 될수 없다고 바울은 주장하고 있다. 사방에 욱여쌈을 당하거나 답답한 일을 받아도 신자들에게는 가장 큰 방패이시요 큰 능력자 이신 하나님 께서 늘그들을 지켜주시기 때문이라고 말한다.
심히 큰 능력의 하나님은 죽음도 이기시고 영원한 참 생명을 보유하고 계신다. 천지에 모든 생명의 근원이 하나님으로부터 왔고 죽음도 이기시고 부활을 보여주신 보배의 주님이 소망으로 신자들에게 언제나 손을 내밀고 계심을 바울은 설명하고 있다.

8. 인간 찾기(해석)
바울은 모든 능려과 생명 죽음을 이기신 부활의 능력은 오직 하나님께로부터 나온다고 주장하고 있다. 그러므로 신자들은 힘든 일이 생겨도 낙심하지 말고 주만 의지하면 문제해결을 받을수있다. 반대로 큰 경사스러운 일이 생겨도 진심으로 겸손과 감사의 마음을 갖는것이 신자의 태도 일것이다.

9. 적용(나)
보배되신 예수만을 더욱 바라고 의지하면서 살아야겠다 

10. 영적 터치(단어/구절)
7절: 우리가 이 보배를 질그릇에 가졌으니

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

