5.하나님 찾기 (관찰)
- 하나님의 소명을 이루게 하시려 보증으로 성령을 주심
6.인간 찾기 (관찰)
- 바울은 장막 집이 무너져 염려하지 말라 말하며 하늘에 집이 있음을 강조한다.
- 하늘로부터 오는 처소를 탄식하며 간절히 사모하라고 하며, 우리의 일을 이루시기 위해 하나님께서 성령을 보증으로 주셨다고 말한다.
- 믿음으로 행하고 보는 것으로 행하지 말라고 말하며 하나님 앞에 가게 될 때에 우리의 몸으로 행한 것을 따라 받게 된다고 말한다.  
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 어려움에 있는 고린도교회 성도들이 믿음의 눈으로 행하길 간절히 바랬다. 당장 눈앞에 놓인 어려움을 보지 말고 하늘에 소망을 보긴 권면하였다.
9. 적용(나): 
- 모든 일에 하나님의 섭리가 있음을 인정한다. 기쁠 때나 슬플 때나 성령님을 의지하고 하늘의 소망을 보며 나아가야겠다. 
- NKFC의 비전도 마찬가지이다. 축구 회원이 많아 경기가 매주 진행되고, 행사가 잘 될 때에 기쁨이 넘치지만 회원 참석이 적을 때에도 기쁜 마음으로 다음 스텝을 기다리며 하나님께 소망을 두어야겠다. 
10. 영적터치(단어/구절)
참으로 이 장막에 있는 우리가 짐진 것 같이 탄식하는 것은 벗고자 함이 아니요 오히려 덧입고자 함이니 죽을 것이 생명에 삼킨 바 되게 하려 함이라
