2023년 12월 18일 고린도후서 6장 11~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
너희: 11, 12(2), 13, 14, 17(2), 18
우리: 11(2), 12, 16
좁아진: 12(2)
믿지 않는 자: 14, 15
하나님: 16(4)
성전: 16(2)

4.주제 만들기: 하나님의 성전으로서 세상과 구별된 삶을 살아가라

5.하나님 찾기 (관찰)
- 너희는 그들 중에서 나와서 따로 있고 부정한 것을 만지지 말라 말씀하심
- 내가 그들 가운데 거하며 두루 행하여 나는 그들의 하나님이 되고 그들은 나의 백성이 되리라 말씀하심

6.인간 찾기 (관찰)
- 바울과 제자들을 향한 고린도인들의 마음이 좁아짐
- 좁아진 마음을 넓히라 권면
- 믿지 않는 자와 멍에를 함께 메지 말라

7.하나님 찾기 (해석)
- 구약 시대에 애굽을 의지하고 앗수르에게 침략당할 당시를 말씀하시며 우상을 믿는 자들을 의지하지거나 그들과 함께 하지 말라고 말씀하심. 이것은 세상과 분리되라는 말씀이 아니라, 하나님을 믿는 믿음 안에 거하고, 믿음 안에서 살아가라는 거룩의 명령이다. 악을 가까이 하지 말고, 악한 일을 도모하는 자와 함께 하지 말라는 명령이다.
- 내가 그들 가운데 거하며 두루 행하여 나는 그들의 하나님이 되고 그들은 나의 백성이 되리라 말씀하시며 구약에 말씀하셨으며 태초부터 소망하신 우리와 함께하시고 우리의 아버지가 되실 것을 말씀하심.

8.인간(해석): 
- 바울 일행을 향한 마음이 좁아졌다는 것은 고린도인들이 세상 속에서 세상과 같이 절제 없는 삶을 살다 보니 믿음이 약해지는 등 바울 일행의 가르침에서 멀어져 그 마음 또한 멀어지거나 거부하는 것을 의미함.
- 우리는 너희가 어떻든 너희를 향한 마음이 이전과 똑같이 넓으니, 너희도 마음을 넓히라 권면함.

9. 적용(나): 
- 내 안에 내주하시며 역사하시는 성령 하나님을 늘 의지하여 내 뜻과 내 편안을 내려놓고 하나님의 뜻을 구하고 그 뜻을 실천하며 살아가도록 노력해야겠다.
- 주위에 악을 꾀하는 자를 분별하여 멀리하는 것도 성령님이 주시는 지혜이고, 내 속에서 일어나는 악한 생각을 소멸하는 것도 성령님의 능력이다.
- 내주하시는 성령님을 의지하여 내 속에 있는 악한 생각을 소멸해야 한다. 


10. 영적터치(단어/구절)  
16 우리는 살아 계신 하나님의 성전이라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

