INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-06', '고린도후서', '7장 1절 ~ 10절', '서로에게 위로가 되는 동역자', '[고후7:1-10]
1 그런즉 사랑하는 자들아 이 약속을 가진 우리는 하나님을 두려워하는 가운데서 거룩함을 온전히 이루어 육과 영의 온갖 더러운 것에서 자신을 깨끗하게 하자
2 마음으로 우리를 영접하라 우리는 아무에게도 불의를 행하지 않고 아무에게도 해롭게 하지 않고 아무에게서도 속여 빼앗은 일이 없노라
3 내가 이 말을 하는 것은 너희를 정죄하려고 하는 것이 아니라 내가 이전에 말하였거니와 너희가 우리 마음에 있어 함께 죽고 함께 살게 하고자 함이라
4 나는 너희를 향하여 담대한 것도 많고 너희를 위하여 자랑하는 것도 많으니 내가 우리의 모든 환난 가운데서도 위로가 가득하고 기쁨이 넘치는도다
5 우리가 마게도냐에 이르렀을 때에도 우리 육체가 편하지 못하였고 사방으로 환난을 당하여 밖으로는 다툼이요 안으로는 두려움이었노라
6 그러나 낙심한 자들을 위로하시는 하나님이 디도가 옴으로 우리를 위로하셨으니
7 그가 온 것뿐 아니요 오직 그가 너희에게서 받은 그 위로로 위로하고 너희의 사모함과 애통함과 나를 위하여 열심 있는 것을 우리에게 보고함으로 나를 더욱 기쁘게 하였느니라
8 그러므로 내가 편지로 너희를 근심하게 한 것을 후회하였으나 지금은 후회하지 아니함은 그 편지가 너희로 잠시만 근심하게 한 줄을 앎이라
9 내가 지금 기뻐함은 너희로 근심하게 한 까닭이 아니요 도리어 너희가 근심함으로 회개함에 이른 까닭이라 너희가 하나님의 뜻대로 근심하게 된 것은 우리에게서 아무 해도 받지 않게 하려 함이라
10 하나님의 뜻대로 하는 근심은 후회할 것이 없는 구원에 이르게 하는 회개를 이루는 것이요 세상 근심은 사망을 이루는 것이니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 12월19일 고린도후서 7장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 함께(3절), 위로(4,6,7절), 후회(8절), 근심(8,9,10절), 후회(8,10절), 회개(9,10절)
4.주제만들기: 서로에게 위로가 되는 동역자
5.하나님 찾기 (관찰)
-낙심하는 자들을 위로하시는 하나님
6.인간 찾기 (관찰)
-바울은 하나님을 두려워하는 가운데서 거룩함을 온전히 이루어 육과 영의 더러운 것에서 자신을 깨끗하게 하자고 한다. 
-바울은 자신의 권면이 함께 죽고 함께 살기 위함임을 말한다.
-바울은 마게도냐에 갔을 때 육체는 온전치 못했고, 환란이 있었으며, 두려움도 있었다고 말한다.
-그 때 위로하시는 하나님이 디도를 통해 위로하셨고, 디도는 고린도교회 성도로부터 받은 위로를 전해주어 기쁘게 되었다고 말한다. 
-처음 편지를 보냈을 때 후회하였으나 후회나 근심하지 않는 것은 바울의 권면으로 회개를 했다는 것에 기쁨이 있기 때문이라고 말한다. 
7.하나님 찾기 (해석) 
8.인간(해석):
-바울은 강하고 완벽한 성격이라 생각할 수 있지만 하나님과 예수님의 사랑을 가슴에 앉고 있었다. 자신의 편지로 고린도교회 성도들이 낙심하진 않을지, 편지의 내용이 너무 과한 것은 아닌지 등을 고민했던 것 같다. 그러나 편지를 통해 고린도교회 성도들이 회개함을 듣고 기뻐하며 자신의 편지가 근심이었지만 기쁨이 되었다고 말했다. 
9. 적용(나): 
- 권면을 받는 사람이 정죄라고 느껴질 땐 사탄의 역사도 있지만 권면하고 조언하는 사람의 행동도 볼 것이다. 우리는 연약해서 완전할 수 없기에 내가 누구를 권면해?라고 생각할 수 있지만 때로는 강한 권면과 조언이 필요한 성도가 있을 것이다. 이 때 근심이 되지 않도록 하려면 영과 육을 깨끗이 하여야 한다. 끊임없이 자신을 단련시켜야겠다.
- 영과 육이 단단해지고 깨끗해지길 소망한다.
10. 영적터치(단어/구절)
- 그런즉 사랑하는 자들아 이 약속을 가진 우리는 하나님을 두려워하는 가운데서 거룩함을 온전히 이루어 육과 영의 온갖 더러운 것에서 자신을 깨끗하게 하자
- 마음으로 우리를 영접하라 우리는 아무에게도 불의를 행하지 않고 아무에게도 해롭게 하지 않고 아무에게서도 속여 빼앗은 일이 없노라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

