8. 인간 찾기(해석)
바울이 얼마나 동역자들을 위하는 마음 그리고 사랑하는지를 알 수 있다.  그 힘은 기본적으로 서로 신뢰하는 마음에서 출발하는것을 보여진다. 특별히 위로의 기쁨을 주는 믿음의 사람 디도를 잠시 소개하면서 피차 고린도 교인들의 바라는 목표를 확인하며 위로와 안심 그리고 신뢰를 굳건하게 세워가는 바울의 모습을 볼수있다. 디도나 바울이나 고린도 성도들이 각자 처해있는 상황 나이, 학연 그리고 지연이 다르더라도 하나님안에서의 간절한 목표라는 동일함을 보여준다. 그 같은 방향을 통해서 서로 깊은 형제애를 느끼며 서로 간절한 마음, 즉 진리를 발견하는 기쁨을 표현하고 있다. 공동체안에서 같은 비전을 알고 품는다는 것은 형제애를 더욱 돈독하게 만드는 증폭제가 될 수 있다.

