바울은 교회에 대하여 말로만 위로하지 않고 믿음의 사람 칭찬받는 디도와 그와 함께 하는 인정받는 또다른 형제를 소개한다. 20절에 ''거액의 연보'' 맡음에 대한 피차 신뢰하는 것을 보면 세상의 가치를 뛰어넘은 바울 과 디도 그리고 다른 형제들의 영적 깊은 관계를 보여준다. 아마 이 끈끈한 사랑의 원동력은 19절의 ''주의 영광''을 바라봄의 목표가 일치하기 때문일것이다.

