2023년 12월23일 고린도후서 9장 1절~15절

1.1분기도

2.본문성경 읽기(3번)

3.반복단어 찾기(형광펜 추천)


	(5,11,13절), 마게도냐인(2,4절), 준비(2,3,4,5절), 억지(5,6절), 심는자(6,9절) 감사(11,12,15절), 은혜(8,14절)


4.주제만들기: 섬김은 지혜롭게 지속성을 가지고

5.하나님 찾기 (관찰)

- 모든 은혜를 넘치게 하시고, 착한 일을 하게 하심


	자에게 씨와 먹을 양식을 주심, 풍성하게 하시고, 열매를 더하심


6.인간 찾기 (관찰)


	형제들을 고린도로 보낸 것은 예루살렘에 필요한 섬김이 잘 준비되도록 하기 위함을 알림



	잘 준비되어야 하는건 바울이 방문했을 때 섬김으로 인해 성도들이 부담되지 않도록 하기 위함을 알림
	심는 자는 적게 걷고, 많이 심는 자는 많이 걷는다고 말하며 마음에 부담이 되지 말고 억지로 하지도 말라고 말하며, 많은 양보단 즐겨내는 자를 사랑한다는 말로 부담이 되지 않게 함. 



	통해 하나님께 감사하게 하며, 복음을 믿고, 순종하는 것과,  하나님께 영광돌린다고 말함. 


7.하나님 찾기 (해석) 


	통해 자신의 역치를 뛰어넘으면 하나님께서 은혜를 넘치게 해주심.


8.인간(해석):


	고린도 교회의 섬김이 다른 성도들에게 큰 도전이 되었다고 말하며, 섬김이 잘 준비되도록 형제들을 보냈다고 설명함. 
	방문할 때 급히 섬김이 이루어진다면 성도들이 부담을 갖게 되는데, 이를 방지하기 위해 조금씩 미리 준비하도록 안내하며 자신의 능력껏 하되 마음에 짐이 되면 안 된다고 말함. 


9. 적용(나): 


	물질적인 섬김은 필수적이다. 그런데 섬김이 신앙의 성장을 가로막는 짐이 되어서는 안된다. 물질의 섬김은 지혜롭게 하고, 자신이 할 수 있는 수준에서 지속성을 가져야 한다. 
	내가 섬길 수 있는 일에 집중하고, 섬김이 필요한 곳에 조금이라도 보탬이 될 수 있도록 주님의 풍성한 은혜가 주어지길 바란다. 



	섬김의 부담으로 고민했던 어리석음이 주마등처럼 지나가는데, 내가 아닌 하나님이 일하셨다는 걸 고백한다. 지금도 일하시는 하나님이 섬김이 필요한 곳곳에 손길을 내밀고 계심을 믿는다.


10. 영적터치(단어/구절)

2절:너희의 열심이 퍽 많은 사람들을 분발하게 하였느니라

11. 믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-11', '고린도후서', '10장 1절 ~ 10절', '제목 없음', '(고린도후서 10장)
1.  너희를 대면하면 유순하고 떠나 있으면 너희에 대하여 담대한 나 바울은 이제 그리스도의 온유와 관용으로 친히 너희를 권하고
2. 또한 우리를 육신에 따라 행하는 자로 여기는 자들에 대하여 내가 담대히 대하는 것 같이 너희와 함께 있을 때에 나로 하여금 이 담대한 태도로 대하지 않게 하기를 구하노라
3. 우리가 육신으로 행하나 육신에 따라 싸우지 아니하노니
4. 우리의 싸우는 무기는 육신에 속한 것이 아니요 오직 어떤 견고한 진도 무너뜨리는 하나님의 능력이라 모든 이론을 무너뜨리며
5. 하나님 아는 것을 대적하여 높아진 것을 다 무너뜨리고 모든 생각을 사로잡아 그리스도에게 복종하게 하니
6. 너희의 복종이 온전하게 될 때에 모든 복종하지 않는 것을 벌하려고 준비하는 중에 있노라
7. 너희는 외모만 보는도다 만일 사람이 자기가 그리스도에게 속한 줄을 믿을진대 자기가 그리스도에게 속한 것 같이 우리도 그러한 줄을 자기 속으로 다시 생각할 것이라
8. 주께서 주신 권세는 너희를 무너뜨리려고 하신 것이 아니요 세우려고 하신 것이니 내가 이에 대하여 지나치게 자랑하여도 부끄럽지 아니하리라
9. 이는 내가 편지들로 너희를 놀라게 하려는 것 같이 생각하지 않게 함이라
10. 그들의 말이 그의 편지들은 무게가 있고 힘이 있으나 그가 몸으로 대할 때는 약하고 그 말도 시원하지 않다 하니

