8.인간(해석): 
- 자기 생각과 기준에 맞춰 자기를 판단하여 스스로 칭찬하는 사람들이 있다.
- 칭찬은 그렇게 스스로 하는 것이 아니라, 그리스도의 복음이 어떻게 전해지고 이 복음으로 개인과 교회가 얼마나 믿음이 자라고 복음 안에서 풍성해졌는가로 판단해야 한다. 
- 우리 일행은 주님의 능력으로 이 교회에 복음을 전했고 이제는 이 교회가 믿음이 커져가고 복음이 풍성해 지기를 바란다. 
- 이 말은 지나친 말이 아니라 사실이고 너희도 이 말이 사실임을 알 것이다.
- 이제도 자랑하는 것은 고린도를 넘어 다른 지역에까지 복음을 전하려 하는 것이다.
- 이 일은 내가 하는 것이 아니요, 주님이 이루시는 일이고 우리는 주 안에서 이루어진 일을 자랑하는 것이다. 
- 자랑하는 자는 주 안에서 자랑해야 한다.

