- 바울은 자신을 용납하라고 말한다.
- 바울은 자신이 열심을 내는 것은 예수님께 정결한 모습으로 가길 원해서인데, 고린도 교회 성도들이 뱀의 미혹처럼 그리스도를 떠나 부패할 것이 두렵다고 말한다.
- 바울은 우리가 전파하지 않은 예수나, 다른 영이나, 다른 복음은 잘 용납한다고 말한다.
- 바울은 자신이 다른 사도에 비해 부족한 것이 없음에도 모든 사람 가운데서 나타냈다고 말하며 고린도교회 성도들을 높이려 자신을 낮췄고 하나님의 복음을 전했다고 말한다. 
- 바울은 고린도교회를 섬기기 위해 다른 교회에 강권해 물질을 받았으며, 고린도교회에 폐를 끼치지 않기 위해 조심했다고 말한다. 그리고 앞으로도 조심할 것이라 말한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울의 고린도교회에 대한 안타까운 마음은 편지를 통해 계속 전달된다. 예수님이 아닌 다른 이야기와 거짓된 영, 그리고 다른 신의 이야기를 너무 쉽게 받아들이는 고린도교회 성도들에게 안타까운 마음을 표현했다.
- 바울은 여러교회에 물질을 후원 받았는데 그것은 고린도교회에 사용하기 위함이라고 말했다. 고린도교회는 특별한 하나님의 은혜가 필요했고, 훈련이 더 필요했나보다. 
- 바울은 고린도교회에 부담을 주지 않기 위해 자신이 한 행동을 말했고, 앞으로도 조심할 것이라고 말했다. 물질로 인해 성도들이 시험에 들지 않도록 하기 위함과 바울의 겸손한 태도를 다시 깨닫게 된다. 
9. 적용(나): 
- 바울이 고린도교회를 사랑한 것 같이, 연약한 NKFC의 나 자신과 회원들을 위해 기도해야겠다. 세상에서 치열하게 살아가는 회원들이 무엇보다 중요한 하나님을 알아가도록 간절히 기도해야겠다. 
- NKFC를 섬기는 손길에 감사하며 후원금을 지혜롭게 하나님이 원하시는 곳에 사용하도록 지혜를 구해야겠다.
