8.인간(해석): 
- 그리스도의 일꾼으로서 심히 수고한 것과 당한 수많은 핍박과 고난에 대해 설명함. 그중에서도 교회에 대한 염려로 인해 날마다 영혼이 눌림을 받는 것이 큰 고통임을 말함.
- 바울은 가짜들의 자랑에 맞서 어쩔 수 없이 자랑할 수 밖에 없는데, 그 자랑하는 것이 자신의 약함이다. 약자와 실족하는 자를 향한 자신의 애타는 마음과 사랑을 나타내는 말이면서 동시에 자신이 약해야 하나님의 능력이 드러나기 때문이다. 바울은 하나님께서 사람들에게 온전히 영광 받으시기를 원하는 것이다.

