자랑: 바율은 평생 자신의 육체를 괴롭게 했던 가시(눈병 또는  간질병)를 고쳐달라고 주님께 3번이나 간구하였다. 그러나 주님께서 의도적으로 고쳐주지 않으셨다. 이유는 진정한 능력을 바울에게 주시고자 하는것이었다. 그 능력은 약할때 겸손하게 주님을 의지하며 매달릴때 주님께서 바울과 함께하심으로 온전케  하시고 강하게 만드심을 바울은 깨닫고 안심하며 기뻐하는 모습을 볼수있다.
이것은 누구에 적용할수 있는것이다.
우리가 구하는 것보다 더 큰 것을 준비하시고 응답하시는 주님을 찬양합니다!

