2023년 12월 30일 고린도후서 12장 11절~21절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 사도(11,12절), 폐를 끼치지(11,12절), 사랑(15,19절), 취하더냐(17,18절), 아니하더냐(18절), 두려워하다(20,21절)
4.주제만들기: 바울의 사랑
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 자신의 사도권과 고린도교회를 향한 자신의 수고, 자신을 비난하는 것에 대한 대응, 고린도교회 여러 문제들에 대한 우려를 말한다. 
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 자신이 사도임을 말하며 사도들과 동등하고, 표적과 능력과 자신의 행동으로 들어났다고 말한다. 당시 바울을 시기 질투하는 무리가 많았던 것 같다. 
- 바울은 고린도교회에 대한 자신의 노력과 수고를 강조한다. 고린도교회를 향한 바울의 사랑을 느낄 수 있는데 수많은 오해와 소문으로 불편함이 있을 수 있는데 그럼에도 고린도교회를 향한 사랑을 굽히지 않았다. 나라면 고린도교회에 자신을 설득할 이유를 느끼지 못했을 것이다. 
- 바울은 자신에 대한 비난에 대해 대응했는데 아마 수없이 무시했을 것이다. 그럼에도 불구하고 흔들리는 고린도교회 성도들을 위해 자신을 변호했다. 믿는 사람들에게 오해를 받고 신뢰가 떨어지면 등을 돌리는데 바울은 하나님께 전적으로 순종했다. 
- 바울은 고린도교회가 가진 여러 문제들에 대해 말한다. 자신이 방문했을 때 이런 문제들로 자신이 슬퍼하지 않게 돌이키도록 권면한다. 한 사람을 위한 바울의 사랑이 느껴진다.
9. 적용(나): 
- 하나님께서 명령하실 때까지 순종하며 해야 할 일에 대해 묵상해야겠다.
- 하나님의 세밀한 음성에 귀 기울여야겠다.
- 해민 전도사님의 암송, 목사님의 경건을 위한 기도, 하나님께서 말씀해주고 계신다. 성장을 위해 스스로를 단련해야 하는데 시간과 환경이 주어지길 기도한다. 
10. 영적터치(단어/구절): 
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-18', '고린도후서', '13장1절 ~ 13절', '제목 없음', '(고린도후서 13장)
1.  내가 이제 세 번째 너희에게 가리니 두세 증인의 입으로 말마다 확정하리라
2. 내가 이미 말하였거니와 지금 떠나 있으나 두 번째 대면하였을 때와 같이 전에 죄 지은 자들과 그 남은 모든 사람에게 미리 말하노니 내가 다시 가면 용서하지 아니하리라
3. 이는 그리스도께서 내 안에서 말씀하시는 증거를 너희가 구함이니 그는 너희에게 대하여 약하지 않고 도리어 너희 안에서 강하시니라
4. 그리스도께서 약하심으로 십자가에 못 박히셨으나 하나님의 능력으로 살아 계시니 우리도 그 안에서 약하나 너희에게 대하여 하나님의 능력으로 그와 함께 살리라
5. 너희는 믿음 안에 있는가 너희 자신을 시험하고 너희 자신을 확증하라 예수 그리스도께서 너희 안에 계신 줄을 너희가 스스로 알지 못하느냐 그렇지 않으면 너희는 버림 받은 자니라
6. 우리가 버림 받은 자 되지 아니한 것을 너희가 알기를 내가 바라고
7. 우리가 하나님께서 너희로 악을 조금도 행하지 않게 하시기를 구하노니 이는 우리가 옳은 자임을 나타내고자 함이 아니라 오직 우리는 버림 받은 자 같을지라도 너희는 선을 행하게 하고자 함이라
8. 우리는 진리를 거슬러 아무 것도 할 수 없고 오직 진리를 위할 뿐이니
9. 우리가 약할 때에 너희가 강한 것을 기뻐하고 또 이것을 위하여 구하니 곧 너희가 온전하게 되는 것이라
10. 그러므로 내가 떠나 있을 때에 이렇게 쓰는 것은 대면할 때에 주께서 너희를 넘어뜨리려 하지 않고 세우려 하여 내게 주신 그 권한을 따라 엄하지 않게 하려 함이라
11. 마지막으로 말하노니 형제들아 기뻐하라 온전하게 되며 위로를 받으며 마음을 같이하며 평안할지어다 또 사랑과 평강의 하나님이 너희와 함께 계시리라 거룩하게 입맞춤으로 서로 문안하라
12. 모든 성도가 너희에게 문안하느니라
13. 주 예수 그리스도의 은혜와 하나님의 사랑과 성령의 교통하심이 너희 무리와 함께 있을지어다

