바울은  연약한 성도들을 향하여 영적으로 약함을 느낄때 그것을 겳핍 또는 버림받았다고  여기지 말것을 당부하고있다.
도리어 기뻐할수 있는것은 완전하신 진리의 하나님이 그 자녀들이 믿음으로 주를  의지한다면 충분히 일으켜주시고  위로하여 주심을 강조하고 있다. 그러므로 스스로 버림 받았다고 여기지말고  정검함으로 피차 서로 위로와 평강을 누리기를 원하는 하나님의 본 마음을  대변하는 모습을 보이고있다.
 뿐만아니라  하나님은 때때로 
연약함 조차도  성장의 발판으로 삼아 영적으로 더욱 세우기를 원하신다.  하나님은 성도끼리 서로 사랑으로 연합하여  선을 이루기를 원하심을 바울은 반복적으로 가르치며 고린도후서 서신서를 마무리하고 있다.

