4.주제 만들기: 다른 복음을 전하는 자는 저주를 받을지어다
5.하나님 찾기 (관찰)
- 우리의 죄를 대속하기 위해 자기의 몸을 주신 예수님
6.인간 찾기 (관찰)
- 하나님이 세운 사도임을 강조하며 갈라디아교회에 인사하는 바울
- 은혜를 속히 떠나 다른 복음을 따르는 사람들
- 복음을 변질되게 하는 사람들
7.하나님 찾기 (해석) 
8.인간(해석): 
- 자신의 사도 됨은 사람이 아니라, 그리스도와 하나님께 있음을 알리는 바울. 
- 왜곡된 복음을 따르는 이들과 왜곡된 복음 때문에 혼란을 겪고 있는 이들에게 바른 복음을 전하기 위해 자신의 사도 됨이 하늘에서 온 것임을 강조.
- 그리스도의 복음을 듣고 교회로 모인 사람 중에 다른 복음을 따르는 사람들이 생겨남.
- 다른 복음은 없다. 그들은 교회를 교란하여 복음을 왜곡시키려는 것이다.
- 바울이 전한 복음을 왜곡시키는 사람들은 저주를 받을 것이다.
- 나는 사람의 기쁨을 위해 살지 않고 하나님의 기쁨을 위해 살고 있는 하나님의 종이니, 내 말을 들어라. 
9. 적용(나): 
- 다른 복음은 없다. 복음을 왜곡시키는 자들이 있을 뿐이고, 그들은 저주를 받을 것이다.
- 복음을 잘 못 알고 있는 이들에게 바른 복음을 가르치는 자가 돼야만 한다. 
- 이런 것들을 간파하는 영적, 지적 날카로움이 있어야 한다.
